        rlog("=== NTL_NAL_SCAN: Map output corruption landscape ===\n");
        rlog("Range: %d to %d, step=%d, res=%dx%d\n", start, end, step, vw, vh);
        rlog("Encoding 1 frame per NTL, logging NAL size and timing.\n\n");

