                            uint64_t v = mp[w];
                            /* Strip MTE tag in bits[59:56] */
                            uint64_t untagged = (v & 0xF000FFFFFFFFFFFFULL) |
                                                ((v & 0x00F0000000000000ULL) ? 0xFFF0000000000000ULL : 0);
