                CFNumberRef wn190 = CFNumberCreate(NULL, kCFNumberIntType, &w190);
                CFNumberRef hn190 = CFNumberCreate(NULL, kCFNumberIntType, &h190);
                CFNumberRef bn190 = CFNumberCreate(NULL, kCFNumberIntType, &bpe190);
