                CFNumberRef custn = CFNumberCreate(NULL, kCFNumberIntType, &cust);
                CFDictionarySetValue(sp227, CFSTR("CustomMarker"), custn);

                IOSurfaceRef s227 = IOSurfaceCreate(sp227);
                if (!s227) { rlog("  Create failed\n"); goto p227_cleanup; }
