                if (base) {
                    memset(base, 0x41, allocSz > 4096 ? 4096 : allocSz);
                    uint64_t *bp = (uint64_t *)base;
                    for (int i = 0; i < 64; i++) bp[i] = 0xBEEF226000000000ULL | i;
                }
