                        /* Try getValue via selector 10 */
                        uint8_t inbuf[256]; memset(inbuf, 0, sizeof(inbuf));
                        uint32_t *kin = (uint32_t *)inbuf;
                        kin[0] = surfID;
                        size_t klen = strlen(probe_keys[ki]);
                        kin[1] = (uint32_t)klen;
                        memcpy(inbuf + 8, probe_keys[ki], klen);
